#!/usr/bin/env python3
"""
Phase 3 — Complete admin UI rebuild.
Run from: /workspaces/dreamos-pwa
"""
import os, sys
ROOT = os.path.dirname(os.path.abspath(__file__))
def write(rel, content):
    path = os.path.join(ROOT, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f: f.write(content)
    print(f"  wrote  {rel}")

FILES = {'lib/admin-api/_base.ts': "// lib/admin-api/_base.ts\n// Admin API fetch wrapper — injects x-admin-password on every request.\n\nexport const API_BASE  = process.env.NEXT_PUBLIC_API_BASE || 'https://dream-os-production.up.railway.app';\nconst ADMIN_PWD        = process.env.NEXT_PUBLIC_ADMIN_PASSWORD || '';\n\nfunction h(extra: Record<string,string> = {}): Record<string,string> {\n  return { 'Content-Type': 'application/json', 'x-admin-password': ADMIN_PWD, ...extra };\n}\n\nexport async function adminGet<T = unknown>(path: string): Promise<T> {\n  const res = await fetch(`${API_BASE}${path}`, { headers: h() });\n  if (!res.ok) throw new Error(`Admin GET ${path} failed: ${res.status}`);\n  return res.json();\n}\n\nexport async function adminPost<T = unknown>(path: string, body?: unknown): Promise<T> {\n  const res = await fetch(`${API_BASE}${path}`, { method: 'POST', headers: h(), body: body !== undefined ? JSON.stringify(body) : undefined });\n  if (!res.ok) throw new Error(`Admin POST ${path} failed: ${res.status}`);\n  return res.json();\n}\n\nexport async function adminPatch<T = unknown>(path: string, body?: unknown): Promise<T> {\n  const res = await fetch(`${API_BASE}${path}`, { method: 'PATCH', headers: h(), body: body !== undefined ? JSON.stringify(body) : undefined });\n  if (!res.ok) throw new Error(`Admin PATCH ${path} failed: ${res.status}`);\n  return res.json();\n}\n\nexport async function adminDelete<T = unknown>(path: string): Promise<T> {\n  const res = await fetch(`${API_BASE}${path}`, { method: 'DELETE', headers: h() });\n  if (!res.ok) throw new Error(`Admin DELETE ${path} failed: ${res.status}`);\n  return res.json();\n}\n\n// Two-phase Cloudinary upload helper.\n// 1. Gets signed params from backend\n// 2. Uploads file directly to Cloudinary\n// 3. Returns { image_url, cloudinary_public_id }\nexport async function adminUploadFile(\n  uploadUrlPath: string,\n  file: File,\n): Promise<{ image_url: string; cloudinary_public_id: string }> {\n  const { upload_url, params } = await adminPost<{ upload_url: string; params: Record<string,unknown> }>(\n    uploadUrlPath, { filename: file.name }\n  );\n  const fd = new FormData();\n  Object.entries(params).forEach(([k, v]) => fd.append(k, String(v)));\n  fd.append('file', file);\n  const up = await fetch(upload_url, { method: 'POST', body: fd });\n  if (!up.ok) throw new Error('Cloudinary upload failed');\n  const data = await up.json();\n  return { image_url: data.secure_url, cloudinary_public_id: data.public_id };\n}\n", 'lib/admin-api/index.ts': "// lib/admin-api/index.ts\n// All admin API types and functions. Single import for all admin pages.\n\nexport { API_BASE } from './_base';\nimport { adminGet, adminPost, adminPatch, adminDelete, adminUploadFile } from './_base';\nexport { adminUploadFile };\n\n// ── Types ─────────────────────────────────────────────────────────────────────\n\nexport type AdminVendor = {\n  id: string; name: string; phone: string; category: string | null;\n  city: string | null; tier: string; status: string;\n  founding_cohort: boolean; discover_eligible: boolean;\n  discover_request_state: string; created_at: string;\n};\n\nexport type AdminCouple = {\n  id: string; name: string; phone: string; wedding_date: string | null;\n  wedding_city: string | null; tier: string; planning_state: string;\n  muse_saves: number; circle_members: number; created_at: string;\n};\n\nexport type InviteCode = {\n  code: string; kind: string; tier: string | null; intended_phone: string | null;\n  notes: string | null; created_by: string | null;\n  created_at: string; consumed_at: string | null; consumed_by_phone: string | null;\n};\n\nexport type ConfigRow = {\n  key: string; value: string; description: string | null; updated_at: string;\n};\n\nexport type AdminImage = {\n  id: string; image_url: string; cloudinary_public_id: string | null;\n  caption: string | null; active: boolean; created_at: string;\n  display_order?: number; sort_order?: number;\n  aesthetic_tags?: string[];\n};\n\nexport type SpotlightItem = AdminImage & {\n  vendor_id: string | null; vendor_name: string | null;\n  vendor_category: string | null; vendor_city: string | null;\n  week_label: string | null;\n};\n\nexport type DiscoverRequest = {\n  id: string; vendor_id: string; vendor_name: string; vendor_category: string;\n  vendor_city: string; discover_request_state: string; created_at: string;\n  portfolio_count: number;\n};\n\nexport type PhotoQueueItem = {\n  id: string; vendor_id: string; image_url: string; caption: string | null;\n  aesthetic_tags: string[]; approval_state: string; created_at: string;\n  vendor: { id: string; business_name: string; category: string; routing_handle: string };\n};\n\nexport type ConversationThread = {\n  id: string; kind: string; state: string; last_message_at: string; created_at: string;\n  vendor_id?: string; vendor_name?: string; vendor_phone?: string;\n  vendor_category?: string; vendor_tier?: string;\n  couple_id?: string; bride_name?: string; bride_phone?: string;\n  wedding_date?: string | null; wedding_city?: string | null;\n};\n\nexport type Message = {\n  id: string; direction: string; channel: string; body: string;\n  sent_by: string; tool_calls: unknown; created_at: string;\n};\n\nexport type HotDate = {\n  id: string; date: string; label: string | null; region: string;\n};\n\n// ── Vendors ───────────────────────────────────────────────────────────────────\n\nexport const getVendors = () => adminGet<{ vendors: AdminVendor[] }>('/api/v2/admin/vendors');\nexport const patchVendorTier = (id: string, tier: string) => adminPatch(`/api/v2/admin/vendors/${id}/tier`, { tier });\nexport const patchVendorDiscover = (id: string) => adminPatch(`/api/v2/admin/vendors/${id}/discover-eligible`, {});\nexport const patchVendorApprove = (id: string) => adminPatch(`/api/v2/admin/vendors/${id}/approve`, {});\nexport const patchVendorRevoke = (id: string) => adminPatch(`/api/v2/admin/vendors/${id}/revoke`, {});\n\n// ── Couples ───────────────────────────────────────────────────────────────────\n\nexport const getCouples = () => adminGet<{ couples: AdminCouple[] }>('/api/v2/admin/couples');\nexport const patchCoupleTier = (id: string, tier: string) => adminPatch(`/api/v2/admin/couples/${id}/tier`, { tier });\n\n// ── Invites ───────────────────────────────────────────────────────────────────\n\nexport const getInvites = () => adminGet<{ invites: InviteCode[] }>('/api/v2/admin/invites');\nexport const getWaLinks = () => adminGet<{ vendor: string; couple: string; note: string }>('/api/v2/admin/invites/whatsapp-links');\nexport const generateInvites = (body: { kind: string; tier?: string; intended_phone?: string; notes?: string; count?: number }) =>\n  adminPost<{ codes: InviteCode[] }>('/api/v2/admin/invites/generate', body);\nexport const deleteInvite = (code: string) => adminDelete(`/api/v2/admin/invites/${code}`);\n\n// ── Config ────────────────────────────────────────────────────────────────────\n\nexport const getConfig = () => adminGet<{ rows: ConfigRow[]; config: Record<string, string> }>('/api/v2/admin/config');\nexport const patchConfig = (key: string, value: string) => adminPatch(`/api/v2/admin/config/${key}`, { value });\n\n// ── Content helpers (shared pattern) ─────────────────────────────────────────\n\nfunction contentApi(base: string) {\n  return {\n    list:      ()                                                   => adminGet<{ photos: AdminImage[] }>(base),\n    uploadUrl: (filename: string)                                   => adminPost<{ upload_url: string; params: Record<string,unknown> }>(`${base}/upload-url`, { filename }),\n    register:  (body: Partial<AdminImage>)                         => adminPost(base, body),\n    patch:     (id: string, body: Partial<AdminImage>)             => adminPatch(`${base}/${id}`, body),\n    remove:    (id: string)                                        => adminDelete(`${base}/${id}`),\n    upload:    (file: File, extra?: Partial<AdminImage>)           => adminUploadFile(`${base}/upload-url`, file).then(r => adminPost(base, { ...r, ...extra })),\n  };\n}\n\nexport const landingApi     = contentApi('/api/v2/admin/landing-photos');\nexport const exploringApi   = contentApi('/api/v2/admin/exploring-photos');\nexport const musePoolApi    = {\n  ...contentApi('/api/v2/admin/muse-pool'),\n  list: () => adminGet<{ images: AdminImage[]; active_count: number; max: number }>('/api/v2/admin/muse-pool'),\n};\nexport const surpriseApi    = {\n  ...contentApi('/api/v2/admin/surprise-pool'),\n  list: () => adminGet<{ images: AdminImage[]; active_count: number; max: number }>('/api/v2/admin/surprise-pool'),\n};\nexport const heroesApi      = {\n  ...contentApi('/api/v2/admin/discover-heroes'),\n  list: () => adminGet<{ heroes: AdminImage[] }>('/api/v2/admin/discover-heroes'),\n};\nexport const spotlightApi   = {\n  list:      ()                                                      => adminGet<{ spotlight: SpotlightItem[] }>('/api/v2/admin/spotlight'),\n  uploadUrl: (filename: string)                                      => adminPost<{ upload_url: string; params: Record<string,unknown> }>('/api/v2/admin/spotlight/upload-url', { filename }),\n  register:  (body: Partial<SpotlightItem>)                        => adminPost('/api/v2/admin/spotlight', body),\n  patch:     (id: string, body: Partial<SpotlightItem>)            => adminPatch(`/api/v2/admin/spotlight/${id}`, body),\n  remove:    (id: string)                                          => adminDelete(`/api/v2/admin/spotlight/${id}`),\n  upload:    (file: File, extra?: Partial<SpotlightItem>)          => adminUploadFile('/api/v2/admin/spotlight/upload-url', file).then(r => adminPost('/api/v2/admin/spotlight', { ...r, ...extra })),\n};\n\n// ── Approvals ─────────────────────────────────────────────────────────────────\n\nexport const getPhotoQueue = (params?: { state?: string; category?: string }) => {\n  const qs = new URLSearchParams(params as Record<string,string> ?? {}).toString();\n  return adminGet<{ photos: PhotoQueueItem[] }>(`/api/v2/admin/photos/queue${qs ? '?' + qs : ''}`);\n};\nexport const approvePhoto  = (id: string)                          => adminPost(`/api/v2/admin/photos/${id}/approve`, {});\nexport const rejectPhoto   = (id: string, reason?: string)        => adminPost(`/api/v2/admin/photos/${id}/reject`, { reason });\nexport const getDiscoverQueue = ()                                 => adminGet<{ requests: DiscoverRequest[] }>('/api/v2/admin/discover/requests');\nexport const grantDiscover    = (vendorId: string)                => adminPost(`/api/v2/admin/discover/grant/${vendorId}`, {});\nexport const denyDiscover     = (vendorId: string)                => adminPost(`/api/v2/admin/discover/deny/${vendorId}`, {});\nexport const revokeDiscover   = (vendorId: string)                => adminPost(`/api/v2/admin/discover/revoke/${vendorId}`, {});\n\n// ── Conversations ─────────────────────────────────────────────────────────────\n\nexport const getVendorThreads = (offset = 0) => adminGet<{ threads: ConversationThread[] }>(`/api/v2/admin/conversations/vendors?limit=20&offset=${offset}`);\nexport const getBrideThreads  = (offset = 0) => adminGet<{ threads: ConversationThread[] }>(`/api/v2/admin/conversations/brides?limit=20&offset=${offset}`);\nexport const getMessages      = (id: string) => adminGet<{ messages: Message[] }>(`/api/v2/admin/conversations/${id}/messages`);\n\n// ── Hot Dates ─────────────────────────────────────────────────────────────────\n\nexport const getHotDates    = ()                                            => adminGet<{ dates: HotDate[] }>('/api/v2/admin/hot-dates');\nexport const addHotDate     = (body: { date: string; note?: string; region?: string }) => adminPost('/api/v2/admin/hot-dates', body);\nexport const deleteHotDate  = (id: string)                                 => adminDelete(`/api/v2/admin/hot-dates/${id}`);\n\n// ── Couture ───────────────────────────────────────────────────────────────────\n\nexport const getCoutureVendors  = () => adminGet<{ vendors: AdminVendor[] }>('/api/v2/admin/couture');\nexport const setCoutureEligible = (vendorId: string, eligible: boolean) => adminPost(`/api/v2/admin/couture/eligible/${vendorId}`, { eligible });\n", 'app/admin/layout.tsx': '\'use client\';\nimport { useEffect, useState } from \'react\';\nimport { useRouter, usePathname } from \'next/navigation\';\n\nconst FONTS = `\n  @import url(\'https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;1,300&family=DM+Sans:wght@300;400&family=Jost:wght@200;300;400&display=swap\');\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  body { background: #0A0908; color: #F5F0E8; -webkit-font-smoothing: antialiased; }\n  ::-webkit-scrollbar { width: 2px; } ::-webkit-scrollbar-thumb { background: rgba(201,168,76,0.3); border-radius: 2px; }\n  @keyframes fadeUp { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }\n  @keyframes shimmer { 0%{opacity:0.4} 50%{opacity:0.7} 100%{opacity:0.4} }\n  .fade-up { animation: fadeUp 280ms cubic-bezier(0.22,1,0.36,1) both; }\n  .shimmer { animation: shimmer 1.4s ease-in-out infinite; }\n  input, select, textarea { font-family: inherit; color: #F5F0E8 !important; }\n  input::placeholder, textarea::placeholder { color: rgba(245,240,232,0.25) !important; }\n  button { cursor: pointer; -webkit-tap-highlight-color: transparent; }\n`;\n\nconst G = \'#C9A84C\';\nconst BG = \'#0A0908\';\nconst BORDER = \'rgba(201,168,76,0.15)\';\nconst INK = \'#F5F0E8\';\nconst SOFT = \'rgba(245,240,232,0.5)\';\nconst SIDEBAR_W = 220;\n\nconst NAV = [\n  { group: \'OVERVIEW\', items: [\n    { label: \'Dashboard\',   path: \'/admin\',                        icon: \'◈\' },\n  ]},\n  { group: \'PEOPLE\', items: [\n    { label: \'Makers\',      path: \'/admin/makers\',                 icon: \'✦\' },\n    { label: \'Portfolios\',  path: \'/admin/vendors/portfolio\',      icon: \'⬡\' },\n    { label: \'Dreamers\',    path: \'/admin/dreamers\',               icon: \'♡\' },\n    { label: \'Invites\',     path: \'/admin/invites\',                icon: \'⌘\' },\n  ]},\n  { group: \'CONTENT\', items: [\n    { label: \'Landing\',     path: \'/admin/content/landing\',        icon: \'⬡\' },\n    { label: \'Exploring\',   path: \'/admin/content/exploring\',      icon: \'◎\' },\n    { label: \'Heroes\',      path: \'/admin/content/heroes\',         icon: \'★\' },\n    { label: \'Spotlight\',   path: \'/admin/content/spotlight\',      icon: \'◐\' },\n    { label: \'Muse Pool\',   path: \'/admin/content/muse-pool\',      icon: \'♡\' },\n    { label: \'Surprise Me\', path: \'/admin/content/surprise-me\',    icon: \'✦\' },\n  ]},\n  { group: \'APPROVALS\', items: [\n    { label: \'Photos\',      path: \'/admin/approvals/photos\',       icon: \'⬡\' },\n    { label: \'Discover\',    path: \'/admin/approvals/discover\',     icon: \'◈\' },\n  ]},\n  { group: \'CONVERSATIONS\', items: [\n    { label: \'Vendors\',     path: \'/admin/conversations/vendors\',  icon: \'◎\' },\n    { label: \'Brides\',      path: \'/admin/conversations/brides\',   icon: \'◎\' },\n  ]},\n  { group: \'COMMERCE\', items: [\n    { label: \'Couture\',     path: \'/admin/couture\',                icon: \'✦\' },\n    { label: \'Hot Dates\',   path: \'/admin/hot-dates\',              icon: \'◈\' },\n  ]},\n  { group: \'CONFIG\', items: [\n    { label: \'AI Caps\',     path: \'/admin/config\',                 icon: \'⚙\' },\n  ]},\n];\n\nexport default function AdminLayout({ children }: { children: React.ReactNode }) {\n  const router   = useRouter();\n  const pathname = usePathname();\n  const [authed, setAuthed]   = useState(false);\n  const [navOpen, setNavOpen] = useState(false);\n\n  useEffect(() => {\n    const s = typeof window !== \'undefined\' ? localStorage.getItem(\'admin_session\') : null;\n    if (!s && pathname !== \'/admin/login\') router.replace(\'/admin/login\');\n    else setAuthed(true);\n  }, [pathname, router]);\n\n  if (!authed && pathname !== \'/admin/login\') return null;\n  if (pathname === \'/admin/login\') return <><style>{FONTS}</style>{children}</>;\n\n  const isActive = (path: string) =>\n    path === \'/admin\' ? pathname === \'/admin\' : pathname.startsWith(path);\n\n  const sidebarContent = (\n    <div style={{ display: \'flex\', flexDirection: \'column\', height: \'100%\', background: \'#0D0B09\', borderRight: `0.5px solid ${BORDER}` }}>\n      <div style={{ padding: \'28px 20px 20px\', flexShrink: 0 }}>\n        <div style={{ fontFamily: \'"Cormorant Garamond", serif\', fontStyle: \'italic\', fontWeight: 300, fontSize: 18, color: INK }}>The Dream Wedding</div>\n        <div style={{ fontFamily: \'"Jost", sans-serif\', fontWeight: 200, fontSize: 7, color: G, letterSpacing: \'0.35em\', textTransform: \'uppercase\' as const, marginTop: 4 }}>Control Room</div>\n        <div style={{ height: \'0.5px\', background: `linear-gradient(to right, ${G}55, transparent)`, marginTop: 16 }} />\n      </div>\n      <nav style={{ flex: 1, overflowY: \'auto\' as const, paddingBottom: 24, scrollbarWidth: \'none\' as const }}>\n        {NAV.map(({ group, items }) => (\n          <div key={group}>\n            <div style={{ fontFamily: \'"Jost", sans-serif\', fontWeight: 200, fontSize: 7, color: \'rgba(201,168,76,0.4)\', letterSpacing: \'0.35em\', textTransform: \'uppercase\' as const, padding: \'18px 20px 6px\' }}>{group}</div>\n            {items.map(({ label, path, icon }) => {\n              const active = isActive(path);\n              return (\n                <button key={path} onClick={() => { router.push(path); setNavOpen(false); }} style={{ display: \'flex\', alignItems: \'center\', gap: 10, width: \'100%\', textAlign: \'left\' as const, padding: \'10px 20px 10px 16px\', border: \'none\', outline: \'none\', background: active ? \'rgba(201,168,76,0.08)\' : \'transparent\', color: active ? G : SOFT, borderLeft: `2px solid ${active ? G : \'transparent\'}`, fontFamily: \'"DM Sans", sans-serif\', fontWeight: active ? 400 : 300, fontSize: 13, transition: \'all 0.15s ease\', minHeight: 44 }}>\n                  <span style={{ fontSize: 10, width: 14, flexShrink: 0, opacity: active ? 1 : 0.5 }}>{icon}</span>\n                  {label}\n                </button>\n              );\n            })}\n          </div>\n        ))}\n      </nav>\n      <div style={{ padding: \'16px 20px\', borderTop: `0.5px solid ${BORDER}`, flexShrink: 0 }}>\n        <button onClick={() => { localStorage.removeItem(\'admin_session\'); router.replace(\'/admin/login\'); }} style={{ background: \'none\', border: \'none\', fontFamily: \'"Jost", sans-serif\', fontWeight: 200, fontSize: 8, letterSpacing: \'0.22em\', textTransform: \'uppercase\' as const, color: SOFT, padding: 0, minHeight: 44, display: \'flex\', alignItems: \'center\' }}>Sign Out</button>\n      </div>\n    </div>\n  );\n\n  return (\n    <>\n      <style>{FONTS}</style>\n      {navOpen && <div onClick={() => setNavOpen(false)} style={{ position: \'fixed\', inset: 0, background: \'rgba(0,0,0,0.75)\', zIndex: 199, backdropFilter: \'blur(4px)\' }} />}\n      <div style={{ position: \'fixed\', top: 0, left: navOpen ? 0 : -SIDEBAR_W - 10, bottom: 0, width: SIDEBAR_W, zIndex: 200, transition: \'left 300ms cubic-bezier(0.22,1,0.36,1)\' }} id="m-nav">{sidebarContent}</div>\n      <div style={{ position: \'fixed\', top: 0, left: 0, bottom: 0, width: SIDEBAR_W, display: \'none\', flexDirection: \'column\' as const }} id="d-nav">{sidebarContent}</div>\n      <div id="admin-main" style={{ background: BG, minHeight: \'100vh\' }}>\n        <div id="m-bar" style={{ display: \'flex\', alignItems: \'center\', justifyContent: \'space-between\', padding: \'0 20px\', height: 56, borderBottom: `0.5px solid ${BORDER}`, background: \'#0D0B09\', position: \'sticky\', top: 0, zIndex: 100 }}>\n          <button onClick={() => setNavOpen(o => !o)} style={{ background: \'none\', border: \'none\', padding: 8, display: \'flex\', flexDirection: \'column\', gap: 5, minWidth: 44, minHeight: 44, alignItems: \'center\', justifyContent: \'center\' }}>\n            <div style={{ width: 20, height: 1.5, background: INK }} />\n            <div style={{ width: 14, height: 1.5, background: INK }} />\n            <div style={{ width: 20, height: 1.5, background: INK }} />\n          </button>\n          <div style={{ fontFamily: \'"Cormorant Garamond", serif\', fontStyle: \'italic\', fontSize: 17, fontWeight: 300, color: INK }}>TDW</div>\n          <div style={{ width: 44 }} />\n        </div>\n        <div style={{ padding: \'24px 20px 100px\', maxWidth: 960, margin: \'0 auto\' }} className="fade-up">{children}</div>\n      </div>\n      <style>{`@media(min-width:768px){#d-nav{display:flex!important;}#m-bar{display:none!important;}#m-nav{display:none!important;}#admin-main{margin-left:${SIDEBAR_W}px;}}`}</style>\n    </>\n  );\n}\n', 'app/admin/login/page.tsx': '\'use client\';\nimport { useState } from \'react\';\nimport { useRouter } from \'next/navigation\';\n\nconst PWD = process.env.NEXT_PUBLIC_ADMIN_PASSWORD ?? \'\';\nconst G = \'#C9A84C\';\nconst INK = \'#F5F0E8\';\nconst SOFT = \'rgba(245,240,232,0.45)\';\nconst BORDER = \'rgba(201,168,76,0.2)\';\n\nexport default function AdminLogin() {\n  const router = useRouter();\n  const [password, setPassword] = useState(\'\');\n  const [error, setError]       = useState(\'\');\n  const [loading, setLoading]   = useState(false);\n\n  function handleLogin() {\n    setLoading(true); setError(\'\');\n    setTimeout(() => {\n      if (password === PWD) {\n        localStorage.setItem(\'admin_session\', \'true\');\n        router.replace(\'/admin\');\n      } else {\n        setError(\'Incorrect password.\');\n        setLoading(false);\n      }\n    }, 400);\n  }\n\n  return (\n    <div style={{ minHeight: \'100vh\', background: \'#0A0908\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', padding: 24 }}>\n      <div style={{ width: \'100%\', maxWidth: 360 }}>\n        <div style={{ textAlign: \'center\', marginBottom: 52 }}>\n          <p style={{ fontFamily: \'"Cormorant Garamond", serif\', fontStyle: \'italic\', fontWeight: 300, fontSize: 26, color: INK, marginBottom: 6 }}>The Dream Wedding</p>\n          <p style={{ fontFamily: \'"Jost", sans-serif\', fontWeight: 200, fontSize: 8, color: G, letterSpacing: \'0.4em\', textTransform: \'uppercase\' }}>Control Room</p>\n          <div style={{ height: \'0.5px\', background: `linear-gradient(to right, transparent, ${G}44, transparent)`, marginTop: 20 }} />\n        </div>\n\n        <div style={{ marginBottom: 12 }}>\n          <p style={{ fontFamily: \'"Jost", sans-serif\', fontWeight: 200, fontSize: 8, color: SOFT, letterSpacing: \'0.22em\', textTransform: \'uppercase\', marginBottom: 10 }}>Password</p>\n          <input\n            type="password"\n            value={password}\n            onChange={e => setPassword(e.target.value)}\n            onKeyDown={e => e.key === \'Enter\' && handleLogin()}\n            autoFocus\n            style={{ width: \'100%\', background: \'rgba(255,255,255,0.04)\', border: `0.5px solid ${BORDER}`, borderRadius: 10, padding: \'14px 16px\', fontFamily: \'"DM Sans", sans-serif\', fontWeight: 300, fontSize: 15, color: INK, outline: \'none\', minHeight: 52 }}\n          />\n        </div>\n\n        {error && <p style={{ fontFamily: \'"DM Sans", sans-serif\', fontSize: 12, color: \'#E05C5C\', marginBottom: 12 }}>{error}</p>}\n\n        <button\n          onClick={handleLogin}\n          disabled={loading || !password}\n          style={{ width: \'100%\', background: !password || loading ? \'rgba(201,168,76,0.25)\' : G, border: \'none\', borderRadius: 10, padding: \'16px 0\', fontFamily: \'"Jost", sans-serif\', fontWeight: 300, fontSize: 10, letterSpacing: \'0.25em\', textTransform: \'uppercase\', color: !password || loading ? \'rgba(201,168,76,0.5)\' : \'#0A0908\', minHeight: 52, cursor: !password || loading ? \'not-allowed\' : \'pointer\', marginTop: 4 }}\n        >\n          {loading ? \'Entering…\' : \'Enter\'}\n        </button>\n      </div>\n    </div>\n  );\n}\n', 'app/admin/page.tsx': '\'use client\';\nimport { useEffect, useState } from \'react\';\nimport { PageHeader, StatCard, T } from \'./_components/AdminUI\';\nimport { getVendors, getCouples, getInvites, getPhotoQueue, getDiscoverQueue } from \'../../lib/admin-api/index\';\n\nexport default function AdminDashboard() {\n  const [stats, setStats] = useState({ vendors: 0, couples: 0, pending_photos: 0, pending_discover: 0, unused_invites: 0 });\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    Promise.all([\n      getVendors().catch(() => ({ vendors: [] })),\n      getCouples().catch(() => ({ couples: [] })),\n      getPhotoQueue({ state: \'pending\' }).catch(() => ({ photos: [] })),\n      getDiscoverQueue().catch(() => ({ requests: [] })),\n      getInvites().catch(() => ({ invites: [] })),\n    ]).then(([v, c, p, d, i]) => {\n      setStats({\n        vendors:          (v as any).vendors?.length ?? 0,\n        couples:          (c as any).couples?.length ?? 0,\n        pending_photos:   (p as any).photos?.length ?? 0,\n        pending_discover: (d as any).requests?.filter((r: any) => r.discover_request_state === \'under_review\').length ?? 0,\n        unused_invites:   (i as any).invites?.filter((x: any) => !x.consumed_at).length ?? 0,\n      });\n      setLoading(false);\n    });\n  }, []);\n\n  const timeStr = new Date().toLocaleString(\'en-IN\', { weekday: \'long\', day: \'numeric\', month: \'long\' });\n\n  return (\n    <div>\n      <div style={{ marginBottom: 32 }}>\n        <p style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 9, color: T.soft, letterSpacing: \'0.25em\', textTransform: \'uppercase\' as const, marginBottom: 4 }}>{timeStr}</p>\n        <h1 style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontWeight: 300, fontSize: 34, color: T.ink, lineHeight: 1.1 }}>Control Room</h1>\n        <div style={{ height: \'0.5px\', background: `linear-gradient(to right, ${T.gold}44, transparent)`, marginTop: 16 }} />\n      </div>\n      {loading ? (\n        <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(2,1fr)\', gap: 12 }}>\n          {[1,2,3,4,5].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 88 }} />)}\n        </div>\n      ) : (\n        <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(2,1fr)\', gap: 12 }}>\n          <StatCard label="Makers" value={stats.vendors} sub="Total vendors" />\n          <StatCard label="Dreamers" value={stats.couples} sub="Total couples" />\n          <StatCard label="Photo Queue" value={stats.pending_photos} sub="Pending approval" />\n          <StatCard label="Discover Queue" value={stats.pending_discover} sub="Under review" />\n          <StatCard label="Open Invites" value={stats.unused_invites} sub="Unconsumed codes" />\n        </div>\n      )}\n      <div style={{ marginTop: 36, background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 14, padding: 20 }}>\n        <p style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.25em\', textTransform: \'uppercase\' as const, marginBottom: 12 }}>Quick Links</p>\n        {[[\'Generate Invites\',\'/admin/invites\'],[\'Upload Muse Pool\',\'/admin/content/muse-pool\'],[\'Upload Surprise Me\',\'/admin/content/surprise-me\'],[\'Approve Photos\',\'/admin/approvals/photos\'],[\'AI Caps\',\'/admin/config\']].map(([label,path]) => (\n          <a key={path} href={path} style={{ display: \'flex\', alignItems: \'center\', justifyContent: \'space-between\', padding: \'14px 0\', borderBottom: `0.5px solid ${T.border}`, textDecoration: \'none\', color: T.soft, fontFamily: T.ff.body, fontSize: 14, fontWeight: 300 }}>\n            {label}<span style={{ color: T.gold }}>→</span>\n          </a>\n        ))}\n      </div>\n    </div>\n  );\n}\n', 'app/admin/_components/AdminUI.tsx': '\'use client\';\n// app/admin/_components/AdminUI.tsx\n// Shared components for the admin portal.\n// All design tokens live here — import from this file only.\n\nimport { useEffect, useRef, useState } from \'react\';\nimport type { ReactNode, DragEvent as ReactDragEvent } from \'react\';\n\n// ── Design tokens ─────────────────────────────────────────────────────────────\nexport const T = {\n  bg:           \'#0A0908\',\n  card:         \'rgba(255,255,255,0.04)\',\n  cardHover:    \'rgba(255,255,255,0.07)\',\n  border:       \'rgba(201,168,76,0.15)\',\n  borderStrong: \'rgba(201,168,76,0.3)\',\n  gold:         \'#C9A84C\',\n  ink:          \'#F5F0E8\',\n  soft:         \'rgba(245,240,232,0.5)\',\n  muted:        \'rgba(245,240,232,0.3)\',\n  danger:       \'#E05C5C\',\n  success:      \'#5CE0A0\',\n  ff: {\n    display: \'"Cormorant Garamond", serif\',\n    body:    \'"DM Sans", sans-serif\',\n    label:   \'"Jost", sans-serif\',\n  },\n};\n\n// ── PageHeader ────────────────────────────────────────────────────────────────\nexport function PageHeader({ title, sub, action }: { title: string; sub?: string; action?: ReactNode }) {\n  return (\n    <div style={{ display: \'flex\', alignItems: \'flex-start\', justifyContent: \'space-between\', marginBottom: 28, gap: 16 }}>\n      <div>\n        <h1 style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontWeight: 300, fontSize: 28, color: T.ink, lineHeight: 1.1, marginBottom: sub ? 4 : 0 }}>{title}</h1>\n        {sub && <p style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 10, color: T.soft, letterSpacing: \'0.18em\', textTransform: \'uppercase\' }}>{sub}</p>}\n      </div>\n      {action && <div style={{ flexShrink: 0 }}>{action}</div>}\n    </div>\n  );\n}\n\n// ── StatCard ──────────────────────────────────────────────────────────────────\nexport function StatCard({ label, value, sub }: { label: string; value: string | number; sub?: string }) {\n  return (\n    <div style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: \'18px 20px\' }}>\n      <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.25em\', textTransform: \'uppercase\', marginBottom: 8 }}>{label}</div>\n      <div style={{ fontFamily: T.ff.display, fontWeight: 300, fontSize: 32, color: T.gold, lineHeight: 1 }}>{value}</div>\n      {sub && <div style={{ fontFamily: T.ff.body, fontWeight: 300, fontSize: 11, color: T.muted, marginTop: 6 }}>{sub}</div>}\n    </div>\n  );\n}\n\n// ── GoldBtn ───────────────────────────────────────────────────────────────────\nexport function GoldBtn({ label, onClick, disabled, small }: { label: string; onClick: () => void; disabled?: boolean; small?: boolean }) {\n  return (\n    <button onClick={onClick} disabled={disabled} style={{ background: disabled ? \'rgba(201,168,76,0.2)\' : T.gold, border: \'none\', borderRadius: 10, padding: small ? \'10px 16px\' : \'14px 24px\', fontFamily: T.ff.label, fontWeight: 300, fontSize: small ? 9 : 10, letterSpacing: \'0.2em\', textTransform: \'uppercase\', color: disabled ? \'rgba(201,168,76,0.5)\' : \'#0A0908\', minHeight: 44, cursor: disabled ? \'not-allowed\' : \'pointer\', whiteSpace: \'nowrap\', transition: \'opacity 0.15s\' }}>\n      {label}\n    </button>\n  );\n}\n\n// ── GhostBtn ──────────────────────────────────────────────────────────────────\nexport function GhostBtn({ label, onClick, danger, small }: { label: string; onClick: () => void; danger?: boolean; small?: boolean }) {\n  return (\n    <button onClick={onClick} style={{ background: \'transparent\', border: `0.5px solid ${danger ? T.danger : T.borderStrong}`, borderRadius: 10, padding: small ? \'10px 16px\' : \'14px 24px\', fontFamily: T.ff.label, fontWeight: 200, fontSize: small ? 9 : 10, letterSpacing: \'0.2em\', textTransform: \'uppercase\', color: danger ? T.danger : T.soft, minHeight: 44, whiteSpace: \'nowrap\', transition: \'all 0.15s\' }}>\n      {label}\n    </button>\n  );\n}\n\n// ── Toast ─────────────────────────────────────────────────────────────────────\nexport function Toast({ msg, onDone, error }: { msg: string; onDone: () => void; error?: boolean }) {\n  useEffect(() => { const t = setTimeout(onDone, 2800); return () => clearTimeout(t); }, [onDone]);\n  return (\n    <div style={{ position: \'fixed\', bottom: \'calc(env(safe-area-inset-bottom,0px) + 24px)\', left: \'50%\', transform: \'translateX(-50%)\', background: error ? \'#3A1A1A\' : \'#1A2A1A\', border: `0.5px solid ${error ? T.danger : T.success}`, color: error ? T.danger : T.success, fontFamily: T.ff.label, fontSize: 11, fontWeight: 300, letterSpacing: \'0.15em\', padding: \'12px 24px\', borderRadius: 100, zIndex: 9999, whiteSpace: \'nowrap\', boxShadow: \'0 8px 32px rgba(0,0,0,0.5)\' }}>\n      {msg}\n    </div>\n  );\n}\n\n// ── FieldInput ────────────────────────────────────────────────────────────────\nexport function FieldInput({ label, value, onChange, placeholder, type = \'text\' }: { label: string; value: string; onChange: (v: string) => void; placeholder?: string; type?: string }) {\n  return (\n    <div style={{ marginBottom: 16 }}>\n      <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\', marginBottom: 8 }}>{label}</div>\n      <input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} style={{ width: \'100%\', background: \'rgba(255,255,255,0.04)\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'12px 14px\', fontFamily: T.ff.body, fontSize: 14, fontWeight: 300, color: T.ink, outline: \'none\', minHeight: 44 }} />\n    </div>\n  );\n}\n\n// ── FieldSelect ───────────────────────────────────────────────────────────────\nexport function FieldSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (v: string) => void; options: { value: string; label: string }[] }) {\n  return (\n    <div style={{ marginBottom: 16 }}>\n      <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\', marginBottom: 8 }}>{label}</div>\n      <select value={value} onChange={e => onChange(e.target.value)} style={{ width: \'100%\', background: \'#141210\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'12px 14px\', fontFamily: T.ff.body, fontSize: 14, fontWeight: 300, color: T.ink, outline: \'none\', minHeight: 44, appearance: \'none\' }}>\n        {options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}\n      </select>\n    </div>\n  );\n}\n\n// ── BottomSheet ───────────────────────────────────────────────────────────────\nexport function BottomSheet({ visible, onClose, title, children }: { visible: boolean; onClose: () => void; title: string; children: ReactNode }) {\n  return (\n    <>\n      {visible && <div onClick={onClose} style={{ position: \'fixed\', inset: 0, background: \'rgba(0,0,0,0.75)\', zIndex: 300, backdropFilter: \'blur(4px)\' }} />}\n      <div style={{ position: \'fixed\', bottom: 0, left: 0, right: 0, zIndex: 301, background: \'#111009\', border: `0.5px solid ${T.border}`, borderRadius: \'20px 20px 0 0\', padding: \'0 0 calc(env(safe-area-inset-bottom,0px) + 24px)\', transform: visible ? \'translateY(0)\' : \'translateY(110%)\', transition: \'transform 340ms cubic-bezier(0.22,1,0.36,1)\', maxHeight: \'90vh\', overflowY: \'auto\' }}>\n        <div style={{ display: \'flex\', justifyContent: \'center\', padding: \'12px 0 4px\' }}>\n          <div style={{ width: 36, height: 4, borderRadius: 2, background: T.border }} />\n        </div>\n        <div style={{ display: \'flex\', alignItems: \'center\', justifyContent: \'space-between\', padding: \'8px 24px 20px\' }}>\n          <span style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 22, fontWeight: 300, color: T.ink }}>{title}</span>\n          <button onClick={onClose} style={{ background: \'none\', border: \'none\', color: T.soft, fontSize: 20, padding: 8, minHeight: 44, minWidth: 44, display: \'flex\', alignItems: \'center\', justifyContent: \'center\' }}>✕</button>\n        </div>\n        <div style={{ padding: \'0 24px\' }}>{children}</div>\n      </div>\n    </>\n  );\n}\n\n// ── UploadZone ────────────────────────────────────────────────────────────────\n// Supports both file upload and URL paste.\nexport function UploadZone({ onFile, onUrl, loading, accept = \'image/*\' }: {\n  onFile: (file: File) => Promise<void>;\n  onUrl:  (url: string) => Promise<void>;\n  loading: boolean;\n  accept?: string;\n}) {\n  const fileRef  = useRef<HTMLInputElement>(null);\n  const [tab, setTab]     = useState<\'file\' | \'url\'>(\'file\');\n  const [url, setUrl]     = useState(\'\');\n  const [dragging, setDragging] = useState(false);\n\n  const handleDrop = (e: ReactDragEvent<HTMLDivElement>) => {\n    e.preventDefault(); setDragging(false);\n    const file = e.dataTransfer.files[0];\n    if (file) onFile(file);\n  };\n\n  const tabBtn = (t: \'file\' | \'url\', lbl: string) => (\n    <button onClick={() => setTab(t)} style={{ flex: 1, padding: \'10px 0\', background: tab === t ? \'rgba(201,168,76,0.12)\' : \'transparent\', border: `0.5px solid ${tab === t ? T.gold : T.border}`, borderRadius: 8, fontFamily: T.ff.label, fontSize: 9, fontWeight: 200, letterSpacing: \'0.2em\', textTransform: \'uppercase\' as const, color: tab === t ? T.gold : T.soft, minHeight: 44 }}>{lbl}</button>\n  );\n\n  return (\n    <div style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 14, padding: 20, marginBottom: 24 }}>\n      <div style={{ display: \'flex\', gap: 8, marginBottom: 16 }}>\n        {tabBtn(\'file\', \'From Device\')}\n        {tabBtn(\'url\', \'From URL\')}\n      </div>\n\n      {tab === \'file\' ? (\n        <div\n          onDragOver={e => { e.preventDefault(); setDragging(true); }}\n          onDragLeave={() => setDragging(false)}\n          onDrop={handleDrop}\n          onClick={() => fileRef.current?.click()}\n          style={{ border: `0.5px dashed ${dragging ? T.gold : T.borderStrong}`, borderRadius: 10, padding: \'32px 20px\', textAlign: \'center\', cursor: \'pointer\', background: dragging ? \'rgba(201,168,76,0.06)\' : \'transparent\', transition: \'all 0.2s\', minHeight: 120, display: \'flex\', flexDirection: \'column\' as const, alignItems: \'center\', justifyContent: \'center\', gap: 8 }}\n        >\n          {loading ? (\n            <div style={{ fontFamily: T.ff.label, fontSize: 10, color: T.gold, letterSpacing: \'0.18em\' }} className="shimmer">Uploading…</div>\n          ) : (\n            <>\n              <div style={{ fontSize: 24, opacity: 0.5 }}>↑</div>\n              <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.soft }}>Tap to choose or drag & drop</div>\n              <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.15em\' }}>JPG · PNG · WEBP</div>\n            </>\n          )}\n          <input ref={fileRef} type="file" accept={accept} style={{ display: \'none\' }} onChange={e => { const f = e.target.files?.[0]; if (f) onFile(f); e.target.value = \'\'; }} />\n        </div>\n      ) : (\n        <div style={{ display: \'flex\', gap: 10 }}>\n          <input\n            value={url}\n            onChange={e => setUrl(e.target.value)}\n            placeholder="https://res.cloudinary.com/..."\n            style={{ flex: 1, background: \'rgba(255,255,255,0.04)\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'12px 14px\', fontFamily: T.ff.body, fontSize: 13, color: T.ink, outline: \'none\', minHeight: 44 }}\n          />\n          <GoldBtn label={loading ? \'…\' : \'Add\'} onClick={() => { if (url.trim()) { onUrl(url.trim()); setUrl(\'\'); } }} disabled={!url.trim() || loading} />\n        </div>\n      )}\n    </div>\n  );\n}\n\n// ── ImageGrid ─────────────────────────────────────────────────────────────────\nexport type ImageGridItem = {\n  id: string; image_url: string; caption?: string | null;\n  active: boolean; display_order?: number; sort_order?: number;\n  extra?: ReactNode;\n};\n\nexport function ImageGrid({ items, onToggle, onDelete }: {\n  items: ImageGridItem[];\n  onToggle: (id: string, active: boolean) => void;\n  onDelete: (id: string) => void;\n}) {\n  const [confirmId, setConfirmId] = useState<string | null>(null);\n\n  if (items.length === 0) {\n    return (\n      <div style={{ textAlign: \'center\', padding: \'48px 24px\', color: T.muted }}>\n        <div style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18, marginBottom: 8 }}>No images yet</div>\n        <div style={{ fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.2em\' }}>Upload above to get started</div>\n      </div>\n    );\n  }\n\n  return (\n    <>\n      {confirmId && (\n        <div onClick={() => setConfirmId(null)} style={{ position: \'fixed\', inset: 0, background: \'rgba(0,0,0,0.8)\', zIndex: 400, display: \'flex\', alignItems: \'center\', justifyContent: \'center\', padding: 24 }}>\n          <div onClick={e => e.stopPropagation()} style={{ background: \'#111009\', border: `0.5px solid ${T.border}`, borderRadius: 16, padding: 28, maxWidth: 320, width: \'100%\' }}>\n            <div style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 20, color: T.ink, marginBottom: 8 }}>Delete image?</div>\n            <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.soft, marginBottom: 24 }}>This also removes it from Cloudinary. Cannot be undone.</div>\n            <div style={{ display: \'flex\', gap: 10 }}>\n              <GhostBtn label="Cancel" onClick={() => setConfirmId(null)} />\n              <GhostBtn label="Delete" onClick={() => { onDelete(confirmId); setConfirmId(null); }} danger />\n            </div>\n          </div>\n        </div>\n      )}\n      <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(2, 1fr)\', gap: 12 }}>\n        {items.map(item => (\n          <div key={item.id} style={{ background: T.card, border: `0.5px solid ${item.active ? T.borderStrong : T.border}`, borderRadius: 12, overflow: \'hidden\', opacity: item.active ? 1 : 0.5, transition: \'all 0.2s\' }}>\n            <div style={{ aspectRatio: \'3/4\', position: \'relative\', overflow: \'hidden\', background: \'#1A1614\' }}>\n              {/* eslint-disable-next-line @next/next/no-img-element */}\n              <img src={item.image_url} alt="" style={{ width: \'100%\', height: \'100%\', objectFit: \'cover\', objectPosition: \'center top\' }} loading="lazy" />\n              {!item.active && (\n                <div style={{ position: \'absolute\', inset: 0, background: \'rgba(0,0,0,0.5)\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\' }}>\n                  <span style={{ fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.2em\', color: \'rgba(255,255,255,0.5)\', textTransform: \'uppercase\' }}>Inactive</span>\n                </div>\n              )}\n            </div>\n            {item.caption && (\n              <div style={{ padding: \'8px 10px 4px\', fontFamily: T.ff.body, fontSize: 11, color: T.soft }}>{item.caption}</div>\n            )}\n            {item.extra && <div style={{ padding: \'4px 10px\' }}>{item.extra}</div>}\n            <div style={{ display: \'flex\', gap: 0, borderTop: `0.5px solid ${T.border}`, marginTop: 8 }}>\n              <button onClick={() => onToggle(item.id, item.active)} style={{ flex: 1, padding: \'12px 0\', background: \'transparent\', border: \'none\', fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.18em\', textTransform: \'uppercase\' as const, color: item.active ? T.gold : T.soft, minHeight: 44, borderRight: `0.5px solid ${T.border}` }}>\n                {item.active ? \'Deactivate\' : \'Activate\'}\n              </button>\n              <button onClick={() => setConfirmId(item.id)} style={{ flex: 1, padding: \'12px 0\', background: \'transparent\', border: \'none\', fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.18em\', textTransform: \'uppercase\' as const, color: T.danger, minHeight: 44 }}>\n                Delete\n              </button>\n            </div>\n          </div>\n        ))}\n      </div>\n    </>\n  );\n}\n\n// ── LoadingGrid ───────────────────────────────────────────────────────────────\nexport function LoadingGrid() {\n  return (\n    <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(2, 1fr)\', gap: 12 }}>\n      {[1,2,3,4].map(i => (\n        <div key={i} className="shimmer" style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, aspectRatio: \'3/4\' }} />\n      ))}\n    </div>\n  );\n}\n\n// ── SectionDivider ────────────────────────────────────────────────────────────\nexport function SectionDivider({ label }: { label: string }) {\n  return (\n    <div style={{ display: \'flex\', alignItems: \'center\', gap: 12, margin: \'28px 0 20px\' }}>\n      <div style={{ flex: 1, height: \'0.5px\', background: T.border }} />\n      <span style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.3em\', textTransform: \'uppercase\', whiteSpace: \'nowrap\' }}>{label}</span>\n      <div style={{ flex: 1, height: \'0.5px\', background: T.border }} />\n    </div>\n  );\n}\n\n// ── Counter pill ──────────────────────────────────────────────────────────────\nexport function Counter({ current, max }: { current: number; max: number }) {\n  const pct  = (current / max) * 100;\n  const full = current >= max;\n  return (\n    <div style={{ display: \'flex\', alignItems: \'center\', gap: 12, background: T.card, border: `0.5px solid ${full ? T.gold : T.border}`, borderRadius: 10, padding: \'12px 16px\', marginBottom: 20 }}>\n      <div style={{ flex: 1, height: 3, background: T.border, borderRadius: 2, overflow: \'hidden\' }}>\n        <div style={{ height: \'100%\', width: `${pct}%`, background: full ? T.gold : \'rgba(201,168,76,0.5)\', borderRadius: 2, transition: \'width 0.4s ease\' }} />\n      </div>\n      <span style={{ fontFamily: T.ff.label, fontSize: 10, fontWeight: 200, color: full ? T.gold : T.soft, letterSpacing: \'0.1em\', whiteSpace: \'nowrap\' }}>{current} / {max}</span>\n    </div>\n  );\n}\n', 'app/admin/ContentPage.tsx': "'use client';\n// Shared content page component — used by landing, exploring, heroes, muse-pool, surprise-me\n// Import and render with the appropriate API module.\n\nimport { useEffect, useState, useCallback } from 'react';\nimport { PageHeader, T, Toast, UploadZone, ImageGrid, LoadingGrid, Counter, SectionDivider, type ImageGridItem } from './_components/AdminUI';\nimport { adminUploadFile } from '../../lib/admin-api/_base';\n\nexport type ContentPageConfig = {\n  title:       string;\n  sub?:        string;\n  adminBase:   string;          // e.g. '/api/v2/admin/landing-photos'\n  listKey:     string;          // e.g. 'photos' or 'images' or 'heroes'\n  max?:        number;          // if set, shows counter\n  folder:      string;          // Cloudinary folder label for display\n};\n\nexport default function ContentPage({ cfg }: { cfg: ContentPageConfig }) {\n  const [items, setItems]     = useState<ImageGridItem[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [uploading, setUploading] = useState(false);\n  const [toast, setToast]     = useState('');\n  const [toastErr, setToastErr] = useState(false);\n  const [activeCount, setActiveCount] = useState(0);\n\n  const API_BASE = process.env.NEXT_PUBLIC_API_BASE || 'https://dream-os-production.up.railway.app';\n  const ADMIN_PWD = process.env.NEXT_PUBLIC_ADMIN_PASSWORD || '';\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    try {\n      const res = await fetch(`${API_BASE}${cfg.adminBase}`, { headers: { 'x-admin-password': ADMIN_PWD } });\n      const d = await res.json();\n      const raw = d[cfg.listKey] || d.images || d.photos || d.heroes || [];\n      const mapped: ImageGridItem[] = raw.map((r: any) => ({\n        id: r.id, image_url: r.image_url, caption: r.caption,\n        active: r.active, display_order: r.display_order, sort_order: r.sort_order,\n      }));\n      setItems(mapped);\n      setActiveCount(d.active_count ?? mapped.filter((i: ImageGridItem) => i.active).length);\n    } catch { showToast('Failed to load.', true); }\n    finally { setLoading(false); }\n  }, [cfg.adminBase, cfg.listKey, API_BASE, ADMIN_PWD]);\n\n  useEffect(() => { load(); }, [load]);\n\n  const handleFile = async (file: File) => {\n    setUploading(true);\n    try {\n      const { image_url, cloudinary_public_id } = await adminUploadFile(`${cfg.adminBase}/upload-url`, file);\n      await fetch(`${API_BASE}${cfg.adminBase}`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-admin-password': ADMIN_PWD }, body: JSON.stringify({ image_url, cloudinary_public_id }) });\n      showToast('Uploaded.');\n      load();\n    } catch { showToast('Upload failed.', true); }\n    finally { setUploading(false); }\n  };\n\n  const handleUrl = async (url: string) => {\n    setUploading(true);\n    try {\n      await fetch(`${API_BASE}${cfg.adminBase}`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-admin-password': ADMIN_PWD }, body: JSON.stringify({ image_url: url }) });\n      showToast('Added.');\n      load();\n    } catch { showToast('Failed to add URL.', true); }\n    finally { setUploading(false); }\n  };\n\n  const toggle = async (id: string, currentActive: boolean) => {\n    try {\n      await fetch(`${API_BASE}${cfg.adminBase}/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'x-admin-password': ADMIN_PWD }, body: JSON.stringify({ active: !currentActive }) });\n      setItems(prev => prev.map(i => i.id === id ? { ...i, active: !currentActive } : i));\n      setActiveCount(prev => currentActive ? prev - 1 : prev + 1);\n    } catch { showToast('Failed.', true); }\n  };\n\n  const remove = async (id: string) => {\n    try {\n      await fetch(`${API_BASE}${cfg.adminBase}/${id}`, { method: 'DELETE', headers: { 'x-admin-password': ADMIN_PWD } });\n      setItems(prev => { const updated = prev.filter(i => i.id !== id); setActiveCount(updated.filter(i => i.active).length); return updated; });\n      showToast('Deleted.');\n    } catch { showToast('Failed to delete.', true); }\n  };\n\n  return (\n    <div>\n      <PageHeader title={cfg.title} sub={cfg.sub} />\n\n      {cfg.max && <Counter current={activeCount} max={cfg.max} />}\n\n      <UploadZone\n        onFile={handleFile}\n        onUrl={handleUrl}\n        loading={uploading}\n      />\n\n      <SectionDivider label={`${items.length} image${items.length !== 1 ? 's' : ''}`} />\n\n      {loading ? <LoadingGrid /> : (\n        <ImageGrid items={items} onToggle={toggle} onDelete={remove} />\n      )}\n\n      {toast && <Toast msg={toast} onDone={() => setToast('')} error={toastErr} />}\n    </div>\n  );\n}\n", 'app/admin/makers/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, FieldInput, FieldSelect, BottomSheet, SectionDivider } from \'../_components/AdminUI\';\nimport { getVendors, patchVendorTier, patchVendorDiscover, patchVendorRevoke, type AdminVendor } from \'../../../lib/admin-api/index\';\n\nconst API_BASE  = process.env.NEXT_PUBLIC_API_BASE  || \'https://dream-os-production.up.railway.app\';\nconst ADMIN_PWD = process.env.NEXT_PUBLIC_ADMIN_PASSWORD || \'\';\nconst WA_VENDOR = \'917982159047\';\n\nconst TIERS = [\'trial\',\'essential\',\'signature\',\'prestige\'];\nconst CATEGORIES = [\'photography\',\'videography\',\'makeup\',\'decor\',\'venue\',\'planning\',\'catering\',\'mehendi\',\'music\',\'jewellery\',\'attire\',\'honeymoon\',\'invitation\',\'other\'];\n\nfunction fmt(d: string) { return new Date(d).toLocaleDateString(\'en-IN\', { day: \'numeric\', month: \'short\', year: \'2-digit\' }); }\n\nexport default function MakersPage() {\n  const [vendors, setVendors]     = useState<AdminVendor[]>([]);\n  const [loading, setLoading]     = useState(true);\n  const [search, setSearch]       = useState(\'\');\n  const [filter, setFilter]       = useState(\'all\');\n  const [toast, setToast]         = useState(\'\');\n  const [toastErr, setToastErr]   = useState(false);\n  const [selected, setSelected]   = useState<AdminVendor | null>(null);\n  const [showInvite, setShowInvite] = useState(false);\n\n  // Invite form\n  const [invName, setInvName]     = useState(\'\');\n  const [invPhone, setInvPhone]   = useState(\'\');\n  const [invCat, setInvCat]       = useState(\'\');\n  const [invCity, setInvCity]     = useState(\'\');\n  const [invTier, setInvTier]     = useState(\'trial\');\n  const [inviting, setInviting]   = useState(false);\n  const [inviteResult, setInviteResult] = useState<{ name: string; waLink: string } | null>(null);\n  const [copied, setCopied]       = useState(false);\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getVendors().then(d => { setVendors(d.vendors); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const setTier = async (id: string, tier: string) => {\n    try { await patchVendorTier(id, tier); setVendors(v => v.map(x => x.id === id ? { ...x, tier } : x)); showToast(\'Tier updated.\'); }\n    catch { showToast(\'Failed to update tier.\', true); }\n  };\n\n  const toggleDiscover = async (v: AdminVendor) => {\n    try { await patchVendorDiscover(v.id); setVendors(vs => vs.map(x => x.id === v.id ? { ...x, discover_eligible: !v.discover_eligible } : x)); showToast(v.discover_eligible ? \'Removed from Discover.\' : \'Added to Discover.\'); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  const revoke = async (id: string) => {\n    try { await patchVendorRevoke(id); setVendors(v => v.map(x => x.id === id ? { ...x, status: \'paused\' } : x)); showToast(\'Access revoked.\'); setSelected(null); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  const deleteVendor = async (id: string) => {\n    try {\n      const res = await fetch(`${API_BASE}/api/v2/admin/vendors/${id}`, {\n        method: \'DELETE\',\n        headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD },\n        body: JSON.stringify({ confirm: true }),\n      });\n      if (!res.ok) throw new Error(\'Failed\');\n      setVendors(v => v.filter(x => x.id !== id));\n      showToast(\'Vendor deleted.\');\n      setSelected(null);\n    } catch { showToast(\'Failed to delete.\', true); }\n  };\n\n  const invite = async () => {\n    if (!invName.trim() || !invPhone.trim()) return;\n    setInviting(true);\n    try {\n      const res = await fetch(`${API_BASE}/api/v2/admin/vendors/create`, {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD },\n        body: JSON.stringify({\n          business_name: invName.trim(),\n          phone: invPhone.trim(),\n          category: invCat || undefined,\n          city: invCity.trim() || undefined,\n          tier: invTier,\n        }),\n      });\n      const d = await res.json();\n      if (!res.ok) throw new Error(d.error || \'Failed\');\n      const waLink = `https://wa.me/${WA_VENDOR}?text=Hi`;\n      setInviteResult({ name: invName.trim(), waLink });\n      load();\n      setInvName(\'\'); setInvPhone(\'\'); setInvCat(\'\'); setInvCity(\'\'); setInvTier(\'signature\');\n    } catch (e: any) {\n      showToast(e.message || \'Failed to invite.\', true);\n    } finally {\n      setInviting(false);\n    }\n  };\n\n  const copyInvite = () => {\n    if (!inviteResult) return;\n    const msg = `Hey ${inviteResult.name} — tap this link to get started with your chief of staff: ${inviteResult.waLink}`;\n    navigator.clipboard.writeText(msg).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2500); });\n  };\n\n  const filtered = vendors.filter(v => {\n    const q = search.toLowerCase();\n    const matchSearch = !search || v.name?.toLowerCase().includes(q) || v.phone?.includes(search);\n    const matchFilter = filter === \'all\' || v.tier === filter;\n    return matchSearch && matchFilter;\n  });\n\n  return (\n    <div>\n      <PageHeader\n        title="Makers"\n        sub={`${vendors.length} total vendors`}\n        action={<GoldBtn label="+ Invite" onClick={() => { setShowInvite(true); setInviteResult(null); }} />}\n      />\n\n      <FieldInput label="Search" value={search} onChange={setSearch} placeholder="Name or phone…" />\n\n      <div style={{ display: \'flex\', gap: 8, marginBottom: 24, overflowX: \'auto\' as const, paddingBottom: 4, scrollbarWidth: \'none\' as const }}>\n        {[\'all\', ...TIERS].map(f => (\n          <button key={f} onClick={() => setFilter(f)} style={{ flexShrink: 0, padding: \'8px 16px\', borderRadius: 20, border: `0.5px solid ${filter === f ? T.gold : T.border}`, background: filter === f ? \'rgba(201,168,76,0.1)\' : \'transparent\', fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: filter === f ? T.gold : T.soft, minHeight: 36 }}>{f}</button>\n        ))}\n      </div>\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {[1,2,3].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 72 }} />)}\n        </div>\n      ) : filtered.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>No vendors found</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {filtered.map(v => (\n            <div key={v.id} onClick={() => setSelected(v)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: \'16px\', display: \'flex\', alignItems: \'center\', gap: 12, cursor: \'pointer\', minHeight: 72 }}>\n              <div style={{ flex: 1, minWidth: 0 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, fontWeight: 400, color: T.ink, marginBottom: 2, overflow: \'hidden\', textOverflow: \'ellipsis\', whiteSpace: \'nowrap\' }}>{v.name}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\' }}>{v.category || \'—\'} · {v.city || \'—\'} · {v.phone}</div>\n              </div>\n              <div style={{ display: \'flex\', flexDirection: \'column\' as const, alignItems: \'flex-end\', gap: 4, flexShrink: 0 }}>\n                <span style={{ fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: T.gold, background: \'rgba(201,168,76,0.1)\', border: `0.5px solid rgba(201,168,76,0.3)`, borderRadius: 20, padding: \'3px 10px\' }}>{v.tier}</span>\n                {v.discover_eligible && <span style={{ fontFamily: T.ff.label, fontSize: 7, color: T.success, letterSpacing: \'0.1em\' }}>● Discover</span>}\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* Manage vendor sheet */}\n      <BottomSheet visible={!!selected} onClose={() => setSelected(null)} title={selected?.name || \'\'}>\n        {selected && (\n          <div>\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.15em\', marginBottom: 20 }}>{selected.phone} · Joined {fmt(selected.created_at)}</div>\n            <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\' as const, marginBottom: 10 }}>Set Tier</div>\n            <div style={{ display: \'flex\', gap: 8, marginBottom: 24, flexWrap: \'wrap\' as const }}>\n              {TIERS.map(t => (\n                <button key={t} onClick={() => { setTier(selected.id, t); setSelected(s => s ? { ...s, tier: t } : s); }} style={{ padding: \'10px 18px\', borderRadius: 20, border: `0.5px solid ${selected.tier === t ? T.gold : T.border}`, background: selected.tier === t ? \'rgba(201,168,76,0.1)\' : \'transparent\', fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: selected.tier === t ? T.gold : T.soft, minHeight: 44 }}>{t}</button>\n              ))}\n            </div>\n            <div style={{ display: \'flex\', gap: 10, marginBottom: 16 }}>\n              <GhostBtn label={selected.discover_eligible ? \'Remove from Discover\' : \'Add to Discover\'} onClick={() => { toggleDiscover(selected); setSelected(s => s ? { ...s, discover_eligible: !s.discover_eligible } : s); }} />\n            </div>\n            <GhostBtn label="Revoke Access" onClick={() => revoke(selected.id)} danger />\n            <div style={{ height: 1, background: \'rgba(224,92,92,0.15)\', margin: \'16px 0\' }} />\n            <GhostBtn label="Delete Permanently" onClick={() => deleteVendor(selected.id)} danger />\n            <p style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.1em\', marginTop: 8 }}>Deletes all vendor data — leads, invoices, events, portfolio. Cannot be undone.</p>\n          </div>\n        )}\n      </BottomSheet>\n\n      {/* Invite by phone sheet */}\n      <BottomSheet visible={showInvite} onClose={() => { setShowInvite(false); setInviteResult(null); }} title="Invite a Maker">\n\n        {inviteResult ? (\n          /* ── Success state ── */\n          <div>\n            <div style={{ background: \'rgba(92,224,160,0.08)\', border: `0.5px solid rgba(92,224,160,0.3)`, borderRadius: 12, padding: \'16px 18px\', marginBottom: 20 }}>\n              <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.success, marginBottom: 6 }}>✓ {inviteResult.name} has been invited.</div>\n              <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\' }}>Vendor row created. Send them the link below.</div>\n            </div>\n\n            <div style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: \'16px 18px\', marginBottom: 20 }}>\n              <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.soft, letterSpacing: \'0.2em\', textTransform: \'uppercase\' as const, marginBottom: 10 }}>Share with {inviteResult.name}</div>\n              <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.ink, lineHeight: 1.7, marginBottom: 16 }}>\n                Hey {inviteResult.name} — tap this link to get started with your chief of staff:<br />\n                <span style={{ color: T.gold }}>{inviteResult.waLink}</span>\n              </div>\n              <div style={{ display: \'flex\', gap: 10 }}>\n                <button\n                  onClick={copyInvite}\n                  style={{ flex: 1, background: copied ? \'rgba(92,224,160,0.1)\' : T.card, border: `0.5px solid ${copied ? \'rgba(92,224,160,0.4)\' : T.border}`, borderRadius: 10, padding: \'12px 0\', fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: copied ? T.success : T.soft, minHeight: 44 }}\n                >\n                  {copied ? \'✓ Copied\' : \'Copy Message\'}\n                </button>\n                <a\n                  href={`https://wa.me/?text=${encodeURIComponent(`Hey ${inviteResult.name} — tap this link to get started with your chief of staff: ${inviteResult.waLink}`)}`}\n                  target="_blank"\n                  rel="noreferrer"\n                  style={{ flex: 1, background: T.gold, border: \'none\', borderRadius: 10, padding: \'12px 0\', fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: \'#0A0908\', minHeight: 44, display: \'flex\', alignItems: \'center\', justifyContent: \'center\', textDecoration: \'none\' }}\n                >\n                  Send via WA\n                </a>\n              </div>\n            </div>\n\n            <GhostBtn label="Invite Another" onClick={() => setInviteResult(null)} />\n          </div>\n        ) : (\n          /* ── Form state ── */\n          <div>\n            <FieldInput label="Name" value={invName} onChange={setInvName} placeholder="Kavya Sharma" />\n            <FieldInput label="WhatsApp Number" value={invPhone} onChange={setInvPhone} placeholder="+918757788550" />\n            <FieldSelect\n              label="Category (optional)"\n              value={invCat}\n              onChange={setInvCat}\n              options={[{ value: \'\', label: \'Select category\' }, ...CATEGORIES.map(c => ({ value: c, label: c.charAt(0).toUpperCase() + c.slice(1) }))]}\n            />\n            <FieldInput label="City (optional)" value={invCity} onChange={setInvCity} placeholder="Mumbai" />\n            <FieldSelect\n              label="Starting Tier"\n              value={invTier}\n              onChange={setInvTier}\n              options={[{ value: \'trial\', label: \'Trial\' }, { value: \'essential\', label: \'Essential\' }, { value: \'signature\', label: \'Signature (recommended)\' }, { value: \'prestige\', label: \'Prestige\' }]}\n            />\n            <div style={{ paddingBottom: 12, marginTop: 4 }}>\n              <GoldBtn\n                label={inviting ? \'Creating…\' : \'Create & Get Link\'}\n                onClick={invite}\n                disabled={inviting || !invName.trim() || !invPhone.trim()}\n              />\n            </div>\n          </div>\n        )}\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/dreamers/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GhostBtn, Toast, FieldInput, BottomSheet } from \'../_components/AdminUI\';\nimport { getCouples, patchCoupleTier, type AdminCouple } from \'../../../lib/admin-api/index\';\n\nconst API_BASE  = process.env.NEXT_PUBLIC_API_BASE  || \'https://dream-os-production.up.railway.app\';\nconst ADMIN_PWD = process.env.NEXT_PUBLIC_ADMIN_PASSWORD || \'\';\nconst TIERS = [\'basic\',\'gold\',\'platinum\'];\nfunction fmt(d: string | null) { return d ? new Date(d).toLocaleDateString(\'en-IN\', { day: \'numeric\', month: \'short\', year: \'2-digit\' }) : \'—\'; }\n\nexport default function DreamersPage() {\n  const [couples, setCouples] = useState<AdminCouple[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [search, setSearch]   = useState(\'\');\n  const [selected, setSelected] = useState<AdminCouple | null>(null);\n  const [toast, setToast]     = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n\n  const deleteCouple = async (id: string) => {\n    try {\n      const res = await fetch(`${API_BASE}/api/v2/admin/couples/${id}`, {\n        method: \'DELETE\',\n        headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD },\n        body: JSON.stringify({ confirm: true }),\n      });\n      if (!res.ok) throw new Error(\'Failed\');\n      setCouples(c => c.filter(x => x.id !== id));\n      showToast(\'Couple deleted.\');\n      setSelected(null);\n    } catch { showToast(\'Failed to delete.\', true); }\n  };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getCouples().then(d => { setCouples(d.couples); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const setTier = async (id: string, tier: string) => {\n    try { await patchCoupleTier(id, tier); setCouples(v => v.map(x => x.id === id ? { ...x, tier } : x)); showToast(\'Tier updated.\'); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  const filtered = couples.filter(c => !search || c.name?.toLowerCase().includes(search.toLowerCase()) || c.phone?.includes(search));\n\n  return (\n    <div>\n      <PageHeader title="Dreamers" sub={`${couples.length} total couples`} />\n      <FieldInput label="Search" value={search} onChange={setSearch} placeholder="Name or phone…" />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {[1,2,3].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 72 }} />)}\n        </div>\n      ) : filtered.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>No dreamers found</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {filtered.map(c => (\n            <div key={c.id} onClick={() => setSelected(c)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: 16, display: \'flex\', alignItems: \'center\', gap: 12, cursor: \'pointer\', minHeight: 72 }}>\n              <div style={{ flex: 1, minWidth: 0 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, fontWeight: 400, color: T.ink, marginBottom: 2, overflow: \'hidden\', textOverflow: \'ellipsis\', whiteSpace: \'nowrap\' }}>{c.name}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\' }}>{c.phone} · {c.wedding_city || \'City TBD\'} · {fmt(c.wedding_date)}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, marginTop: 2 }}>{c.muse_saves} saves · {c.circle_members} circle</div>\n              </div>\n              <span style={{ fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: T.gold, background: \'rgba(201,168,76,0.1)\', border: `0.5px solid rgba(201,168,76,0.3)`, borderRadius: 20, padding: \'3px 10px\', flexShrink: 0 }}>{c.tier}</span>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <BottomSheet visible={!!selected} onClose={() => setSelected(null)} title={selected?.name || \'\'}>\n        {selected && (\n          <div>\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.15em\', marginBottom: 20 }}>{selected.phone} · {fmt(selected.created_at)}</div>\n            <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\' as const, marginBottom: 10 }}>Set Tier</div>\n            <div style={{ display: \'flex\', gap: 8, marginBottom: 24 }}>\n              {TIERS.map(t => (\n                <button key={t} onClick={() => { setTier(selected.id, t); setSelected(s => s ? { ...s, tier: t } : s); }} style={{ flex: 1, padding: \'12px 0\', borderRadius: 10, border: `0.5px solid ${selected.tier === t ? T.gold : T.border}`, background: selected.tier === t ? \'rgba(201,168,76,0.1)\' : \'transparent\', fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: selected.tier === t ? T.gold : T.soft, minHeight: 44 }}>{t}</button>\n              ))}\n            </div>\n            <div style={{ height: 1, background: \'rgba(224,92,92,0.15)\', margin: \'8px 0 16px\' }} />\n            <GhostBtn label="Delete Permanently" onClick={() => deleteCouple(selected.id)} danger />\n            <p style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.1em\', marginTop: 8 }}>Deletes all couple data — muse saves, circle, conversations. Cannot be undone.</p>\n          </div>\n        )}\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/invites/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, FieldInput, FieldSelect, BottomSheet, SectionDivider } from \'../_components/AdminUI\';\nimport { getInvites, getWaLinks, generateInvites, deleteInvite, type InviteCode } from \'../../../lib/admin-api/index\';\n\nfunction fmt(d: string) { return new Date(d).toLocaleDateString(\'en-IN\', { day: \'numeric\', month: \'short\', year: \'2-digit\' }); }\n\nexport default function InvitesPage() {\n  const [invites, setInvites]   = useState<InviteCode[]>([]);\n  const [waLinks, setWaLinks]   = useState<{ vendor: string; couple: string }>({ vendor: \'\', couple: \'\' });\n  const [loading, setLoading]   = useState(true);\n  const [showGen, setShowGen]   = useState(false);\n  const [toast, setToast]       = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n  const [copied, setCopied]     = useState(\'\');\n\n  // Gen form state\n  const [kind, setKind]           = useState(\'maker\');\n  const [tier, setTier]           = useState(\'signature\');\n  const [phone, setPhone]         = useState(\'\');\n  const [notes, setNotes]         = useState(\'\');\n  const [count, setCount]         = useState(\'1\');\n  const [generating, setGenerating] = useState(false);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    Promise.all([getInvites(), getWaLinks()]).then(([inv, wa]) => {\n      setInvites(inv.invites);\n      setWaLinks({ vendor: (wa as any).vendor, couple: (wa as any).couple });\n      setLoading(false);\n    }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const copy = (text: string, label: string) => {\n    navigator.clipboard.writeText(text).then(() => { setCopied(label); setTimeout(() => setCopied(\'\'), 2000); });\n  };\n\n  const generate = async () => {\n    setGenerating(true);\n    try {\n      const res = await generateInvites({ kind, tier: tier || undefined, intended_phone: phone.trim() || undefined, notes: notes.trim() || undefined, count: phone.trim() ? 1 : parseInt(count) || 1 });\n      setInvites(prev => [...(res as any).codes.map((c: InviteCode) => ({ ...c, created_at: new Date().toISOString(), consumed_at: null, consumed_by_phone: null, created_by: \'admin\' })), ...prev]);\n      showToast(`${(res as any).codes.length} code${(res as any).codes.length > 1 ? \'s\' : \'\'} generated.`);\n      setShowGen(false); setPhone(\'\'); setNotes(\'\'); setCount(\'1\');\n    } catch { showToast(\'Failed to generate.\', true); }\n    finally { setGenerating(false); }\n  };\n\n  const remove = async (code: string) => {\n    try { await deleteInvite(code); setInvites(prev => prev.filter(i => i.code !== code)); showToast(\'Code deleted.\'); }\n    catch { showToast(\'Failed to delete.\', true); }\n  };\n\n  const active   = invites.filter(i => !i.consumed_at);\n  const consumed = invites.filter(i => i.consumed_at);\n\n  return (\n    <div>\n      <PageHeader title="Invites" sub="WhatsApp links + web codes" action={<GoldBtn label="Generate" onClick={() => setShowGen(true)} />} />\n\n      {/* WA Links */}\n      <div style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 14, padding: 20, marginBottom: 24 }}>\n        <p style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.25em\', textTransform: \'uppercase\' as const, marginBottom: 16 }}>WhatsApp Onboarding Links</p>\n        <p style={{ fontFamily: T.ff.body, fontSize: 12, color: T.muted, marginBottom: 16, lineHeight: 1.5 }}>Share these numbers. When someone messages, the agent onboards them automatically. No invite code needed.</p>\n        {[[\'Vendor (Maker)\', waLinks.vendor], [\'Couple (Dreamer)\', waLinks.couple]].map(([label, link]) => (\n          <div key={label} style={{ display: \'flex\', alignItems: \'center\', justifyContent: \'space-between\', padding: \'14px 0\', borderBottom: `0.5px solid ${T.border}` }}>\n            <div>\n              <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.ink, marginBottom: 2 }}>{label}</div>\n              <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft }}>{link}</div>\n            </div>\n            <button onClick={() => copy(link, label)} style={{ background: copied === label ? \'rgba(201,168,76,0.15)\' : \'rgba(255,255,255,0.05)\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'10px 16px\', fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: copied === label ? T.gold : T.soft, minHeight: 44, minWidth: 80 }}>\n              {copied === label ? \'Copied!\' : \'Copy\'}\n            </button>\n          </div>\n        ))}\n      </div>\n\n      {/* Active codes */}\n      <SectionDivider label={`Active Codes (${active.length})`} />\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>{[1,2].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 10, height: 64 }} />)}</div>\n      ) : active.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'24px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 16 }}>No active codes</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {active.map(inv => (\n            <div key={inv.code} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: 16, display: \'flex\', alignItems: \'center\', gap: 12 }}>\n              <div style={{ flex: 1 }}>\n                <div style={{ fontFamily: \'"Courier New", monospace\', fontSize: 16, color: T.gold, letterSpacing: \'0.15em\', marginBottom: 4 }}>{inv.code}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.soft, letterSpacing: \'0.1em\' }}>\n                  {inv.kind.toUpperCase()} · {inv.tier || \'no tier\'}{inv.intended_phone ? ` · ${inv.intended_phone}` : \'\'}{inv.notes ? ` · ${inv.notes}` : \'\'}\n                </div>\n              </div>\n              <div style={{ display: \'flex\', gap: 8, flexShrink: 0 }}>\n                <button onClick={() => copy(inv.code, inv.code)} style={{ background: \'transparent\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'10px 14px\', fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: copied === inv.code ? T.gold : T.soft, minHeight: 44 }}>{copied === inv.code ? \'✓\' : \'Copy\'}</button>\n                <button onClick={() => remove(inv.code)} style={{ background: \'transparent\', border: `0.5px solid rgba(224,92,92,0.3)`, borderRadius: 8, padding: \'10px 14px\', fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: \'#E05C5C\', minHeight: 44 }}>Del</button>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {consumed.length > 0 && (\n        <>\n          <SectionDivider label={`Used (${consumed.length})`} />\n          <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 6 }}>\n            {consumed.slice(0, 10).map(inv => (\n              <div key={inv.code} style={{ background: \'rgba(255,255,255,0.02)\', border: `0.5px solid ${T.border}`, borderRadius: 10, padding: \'12px 14px\', opacity: 0.6 }}>\n                <div style={{ display: \'flex\', justifyContent: \'space-between\' }}>\n                  <span style={{ fontFamily: \'"Courier New", monospace\', fontSize: 13, color: T.soft }}>{inv.code}</span>\n                  <span style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted }}>{fmt(inv.consumed_at!)}</span>\n                </div>\n                {inv.consumed_by_phone && <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, marginTop: 2 }}>Used by {inv.consumed_by_phone}</div>}\n              </div>\n            ))}\n          </div>\n        </>\n      )}\n\n      {/* Generate sheet */}\n      <BottomSheet visible={showGen} onClose={() => setShowGen(false)} title="Generate Codes">\n        <FieldSelect label="Kind" value={kind} onChange={setKind} options={[{ value: \'maker\', label: \'Maker (Vendor)\' }, { value: \'dreamer\', label: \'Dreamer (Couple)\' }]} />\n        <FieldSelect label="Tier" value={tier} onChange={setTier} options={[{ value: \'trial\', label: \'Trial\' }, { value: \'essential\', label: \'Essential\' }, { value: \'signature\', label: \'Signature\' }, { value: \'prestige\', label: \'Prestige\' }]} />\n        <FieldInput label="Bind to phone (optional)" value={phone} onChange={setPhone} placeholder="+91…" />\n        <FieldInput label="Notes (optional)" value={notes} onChange={setNotes} placeholder="VIP, founding cohort…" />\n        {!phone && <FieldInput label="Count (max 50)" value={count} onChange={setCount} type="number" />}\n        <div style={{ paddingBottom: 12 }}>\n          <GoldBtn label={generating ? \'Generating…\' : \'Generate\'} onClick={generate} disabled={generating} />\n        </div>\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/config/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, Toast } from \'../_components/AdminUI\';\nimport { getConfig, patchConfig, type ConfigRow } from \'../../../lib/admin-api/index\';\n\ntype Group = { label: string; keys: string[] };\n\nconst GROUPS: Group[] = [\n  { label: \'Vendor WhatsApp\',\n    keys: [\'vendor_wa_daily_trial\',\'vendor_wa_daily_essential\',\'vendor_wa_daily_signature\',\'vendor_wa_daily_prestige\',\n           \'vendor_wa_monthly_trial\',\'vendor_wa_monthly_essential\',\'vendor_wa_monthly_signature\',\'vendor_wa_monthly_prestige\'] },\n  { label: \'Vendor PWA\',\n    keys: [\'vendor_pwa_daily_trial\',\'vendor_pwa_daily_essential\',\'vendor_pwa_daily_signature\',\'vendor_pwa_daily_prestige\',\n           \'vendor_pwa_monthly_trial\',\'vendor_pwa_monthly_essential\',\'vendor_pwa_monthly_signature\',\'vendor_pwa_monthly_prestige\'] },\n  { label: \'Couple WhatsApp\',\n    keys: [\'couple_wa_daily_basic\',\'couple_wa_daily_gold\',\'couple_wa_daily_platinum\',\n           \'couple_wa_monthly_basic\',\'couple_wa_monthly_gold\',\'couple_wa_monthly_platinum\'] },\n  { label: \'Couple PWA\',\n    keys: [\'couple_pwa_daily_basic\',\'couple_pwa_daily_gold\',\'couple_pwa_daily_platinum\',\n           \'couple_pwa_monthly_basic\',\'couple_pwa_monthly_gold\',\'couple_pwa_monthly_platinum\'] },\n];\n\nfunction keyLabel(key: string): { tier: string; period: string } {\n  const parts = key.split(\'_\');\n  const tier   = parts[parts.length - 1];\n  const period = key.includes(\'daily\') ? \'Daily\' : \'Monthly\';\n  return { tier: tier.charAt(0).toUpperCase() + tier.slice(1), period };\n}\n\nexport default function ConfigPage() {\n  const [rows, setRows]       = useState<ConfigRow[]>([]);\n  const [edits, setEdits]     = useState<Record<string, string>>({});\n  const [saving, setSaving]   = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [toast, setToast]     = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getConfig().then(d => { setRows(d.rows); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const getValue = (key: string) => edits[key] ?? rows.find(r => r.key === key)?.value ?? \'\';\n  const isDirty  = (key: string) => edits[key] !== undefined && edits[key] !== rows.find(r => r.key === key)?.value;\n\n  const save = async (key: string) => {\n    const val = edits[key];\n    if (!val) return;\n    setSaving(key);\n    try {\n      await patchConfig(key, val);\n      setRows(prev => prev.map(r => r.key === key ? { ...r, value: val } : r));\n      setEdits(prev => { const n = { ...prev }; delete n[key]; return n; });\n      showToast(\'Saved.\');\n    } catch { showToast(\'Failed.\', true); }\n    finally { setSaving(null); }\n  };\n\n  return (\n    <div>\n      <PageHeader title="AI Caps" sub="Daily and monthly message limits per tier — changes take effect immediately" />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 12 }}>\n          {[1,2,3].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 180 }} />)}\n        </div>\n      ) : (\n        GROUPS.map(group => (\n          <div key={group.label} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 14, padding: \'20px\', marginBottom: 16 }}>\n            <p style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.gold, letterSpacing: \'0.3em\', textTransform: \'uppercase\' as const, marginBottom: 16 }}>{group.label}</p>\n            {group.keys.map(key => {\n              const { tier, period } = keyLabel(key);\n              const val  = getValue(key);\n              const dirty = isDirty(key);\n              return (\n                <div key={key} style={{ display: \'flex\', alignItems: \'center\', gap: 12, paddingBottom: 14, marginBottom: 14, borderBottom: `0.5px solid ${T.border}` }}>\n                  <div style={{ flex: 1 }}>\n                    <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.ink, marginBottom: 2 }}>{tier} <span style={{ color: T.soft, fontSize: 11 }}>· {period}</span></div>\n                    <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.08em\' }}>{key}</div>\n                  </div>\n                  <input\n                    type="number"\n                    value={val}\n                    onChange={e => setEdits(prev => ({ ...prev, [key]: e.target.value }))}\n                    style={{ width: 70, background: \'rgba(255,255,255,0.06)\', border: `0.5px solid ${dirty ? T.gold : T.border}`, borderRadius: 8, padding: \'8px 12px\', fontFamily: T.ff.body, fontSize: 15, color: dirty ? T.gold : T.ink, textAlign: \'center\', outline: \'none\', minHeight: 44 }}\n                  />\n                  <button\n                    onClick={() => save(key)}\n                    disabled={!dirty || saving === key}\n                    style={{ background: dirty ? T.gold : \'transparent\', border: `0.5px solid ${dirty ? T.gold : T.border}`, borderRadius: 8, padding: \'8px 14px\', fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: dirty ? \'#0A0908\' : T.muted, minHeight: 44, minWidth: 52, cursor: dirty ? \'pointer\' : \'default\', transition: \'all 0.2s\' }}\n                  >\n                    {saving === key ? \'…\' : \'Save\'}\n                  </button>\n                </div>\n              );\n            })}\n          </div>\n        ))\n      )}\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/couture/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, BottomSheet } from \'../_components/AdminUI\';\nimport { getCoutureVendors, setCoutureEligible, type AdminVendor } from \'../../../lib/admin-api/index\';\n\nexport default function CouturePage() {\n  const [vendors, setVendors] = useState<AdminVendor[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [selected, setSelected] = useState<AdminVendor | null>(null);\n  const [toast, setToast]     = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getCoutureVendors().then(d => { setVendors(d.vendors); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const toggle = async (v: AdminVendor) => {\n    try {\n      await setCoutureEligible(v.id, !(v as any).couture_eligible);\n      setVendors(vs => vs.map(x => x.id === v.id ? { ...x, couture_eligible: !(x as any).couture_eligible } as any : x));\n      showToast((v as any).couture_eligible ? \'Removed from Couture.\' : \'Added to Couture.\');\n      setSelected(null);\n    } catch { showToast(\'Failed.\', true); }\n  };\n\n  return (\n    <div>\n      <PageHeader title="Couture" sub="Invite-only programme vendors" />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {[1,2,3].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 68 }} />)}\n        </div>\n      ) : vendors.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>No vendors yet</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {vendors.map(v => (\n            <div key={v.id} onClick={() => setSelected(v)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: 16, display: \'flex\', alignItems: \'center\', gap: 12, cursor: \'pointer\', minHeight: 68 }}>\n              <div style={{ flex: 1 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.ink, marginBottom: 2 }}>{v.name}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\' }}>{v.category} · {v.city}</div>\n              </div>\n              {(v as any).couture_eligible && <span style={{ fontFamily: T.ff.label, fontSize: 7, color: T.gold, border: `0.5px solid ${T.borderStrong}`, borderRadius: 20, padding: \'3px 10px\', letterSpacing: \'0.12em\', textTransform: \'uppercase\' as const }}>Couture</span>}\n            </div>\n          ))}\n        </div>\n      )}\n\n      <BottomSheet visible={!!selected} onClose={() => setSelected(null)} title={selected?.name || \'\'}>\n        {selected && (\n          <div>\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, marginBottom: 24 }}>{selected.category} · {selected.city} · {selected.tier}</div>\n            <GhostBtn label={(selected as any).couture_eligible ? \'Remove from Couture\' : \'Add to Couture\'} onClick={() => toggle(selected)} danger={(selected as any).couture_eligible} />\n          </div>\n        )}\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/hot-dates/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, FieldInput, BottomSheet, SectionDivider } from \'../_components/AdminUI\';\nimport { getHotDates, addHotDate, deleteHotDate, type HotDate } from \'../../../lib/admin-api/index\';\n\nfunction fmtDate(d: string) {\n  return new Date(d + \'T00:00:00\').toLocaleDateString(\'en-IN\', { weekday: \'short\', day: \'numeric\', month: \'long\', year: \'numeric\' });\n}\n\nexport default function HotDatesPage() {\n  const [dates, setDates]     = useState<HotDate[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [showAdd, setShowAdd] = useState(false);\n  const [date, setDate]       = useState(\'\');\n  const [note, setNote]       = useState(\'\');\n  const [region, setRegion]   = useState(\'All India\');\n  const [adding, setAdding]   = useState(false);\n  const [toast, setToast]     = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n  const [confirmId, setConfirmId] = useState<string | null>(null);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getHotDates().then(d => { setDates(d.dates); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const add = async () => {\n    if (!date) return;\n    setAdding(true);\n    try {\n      await addHotDate({ date, note: note || undefined, region: region || \'All India\' });\n      showToast(\'Date added.\');\n      setShowAdd(false); setDate(\'\'); setNote(\'\'); setRegion(\'All India\');\n      load();\n    } catch { showToast(\'Failed.\', true); }\n    finally { setAdding(false); }\n  };\n\n  const remove = async (id: string) => {\n    try { await deleteHotDate(id); setDates(d => d.filter(x => x.id !== id)); showToast(\'Deleted.\'); setConfirmId(null); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  const upcoming = dates.filter(d => new Date(d.date) >= new Date());\n  const past     = dates.filter(d => new Date(d.date) < new Date());\n\n  return (\n    <div>\n      <PageHeader title="Hot Dates" sub="Vivah Muhurat & auspicious wedding dates" action={<GoldBtn label="Add Date" onClick={() => setShowAdd(true)} />} />\n\n      {confirmId && (\n        <div onClick={() => setConfirmId(null)} style={{ position: \'fixed\', inset: 0, background: \'rgba(0,0,0,0.8)\', zIndex: 400, display: \'flex\', alignItems: \'center\', justifyContent: \'center\', padding: 24 }}>\n          <div onClick={e => e.stopPropagation()} style={{ background: \'#111009\', border: `0.5px solid ${T.border}`, borderRadius: 16, padding: 28, maxWidth: 320, width: \'100%\' }}>\n            <div style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 20, color: T.ink, marginBottom: 16 }}>Delete this date?</div>\n            <div style={{ display: \'flex\', gap: 10 }}>\n              <GhostBtn label="Cancel" onClick={() => setConfirmId(null)} />\n              <GhostBtn label="Delete" onClick={() => remove(confirmId)} danger />\n            </div>\n          </div>\n        </div>\n      )}\n\n      <SectionDivider label={`${upcoming.length} upcoming`} />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 6 }}>\n          {[1,2,3].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 10, height: 56 }} />)}\n        </div>\n      ) : upcoming.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'24px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 16 }}>No upcoming dates</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 6 }}>\n          {upcoming.map(d => (\n            <div key={d.id} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 10, padding: \'14px 16px\', display: \'flex\', alignItems: \'center\', gap: 12 }}>\n              <div style={{ flex: 1 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.gold, marginBottom: 2 }}>{fmtDate(d.date)}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\' }}>{d.label || \'Muhurat\'} · {d.region}</div>\n              </div>\n              <button onClick={() => setConfirmId(d.id)} style={{ background: \'transparent\', border: \'none\', color: T.danger, fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, padding: \'8px 12px\', minHeight: 44 }}>Del</button>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {past.length > 0 && (\n        <>\n          <SectionDivider label={`${past.length} past`} />\n          <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 6, opacity: 0.45 }}>\n            {past.slice(-5).reverse().map(d => (\n              <div key={d.id} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 10, padding: \'12px 16px\', display: \'flex\', alignItems: \'center\', gap: 12 }}>\n                <div style={{ flex: 1 }}>\n                  <div style={{ fontFamily: T.ff.body, fontSize: 13, color: T.soft, marginBottom: 2 }}>{fmtDate(d.date)}</div>\n                  <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted }}>{d.label || \'Muhurat\'}</div>\n                </div>\n                <button onClick={() => setConfirmId(d.id)} style={{ background: \'transparent\', border: \'none\', color: T.danger, fontFamily: T.ff.label, fontSize: 8, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, padding: \'8px 12px\', minHeight: 44 }}>Del</button>\n              </div>\n            ))}\n          </div>\n        </>\n      )}\n\n      <BottomSheet visible={showAdd} onClose={() => setShowAdd(false)} title="Add Hot Date">\n        <FieldInput label="Date (YYYY-MM-DD)" value={date} onChange={setDate} type="date" />\n        <FieldInput label="Label (optional)" value={note} onChange={setNote} placeholder="Akshaya Tritiya, Dev Uthani Ekadashi…" />\n        <FieldInput label="Region" value={region} onChange={setRegion} placeholder="All India" />\n        <div style={{ paddingBottom: 12 }}>\n          <GoldBtn label={adding ? \'Adding…\' : \'Add\'} onClick={add} disabled={adding || !date} />\n        </div>\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/content/landing/page.tsx': "'use client';\nimport ContentPage from '../../ContentPage';\nexport default function LandingPage() {\n  return <ContentPage cfg={{ title: 'Landing Photos', sub: 'Full-bleed slideshow on the landing page', adminBase: '/api/v2/admin/landing-photos', listKey: 'photos', folder: 'landing_photos' }} />;\n}\n", 'app/admin/content/exploring/page.tsx': '\'use client\';\nimport ContentPage from \'../../ContentPage\';\nexport default function ExploringPage() {\n  return <ContentPage cfg={{ title: \'Exploring Photos\', sub: \'"Just Exploring" mood gallery for anonymous visitors\', adminBase: \'/api/v2/admin/exploring-photos\', listKey: \'photos\', folder: \'exploring_photos\' }} />;\n}\n', 'app/admin/content/heroes/page.tsx': "'use client';\nimport ContentPage from '../../ContentPage';\nexport default function HeroesPage() {\n  return <ContentPage cfg={{ title: 'Discover Heroes', sub: 'Hero images shown at top of bride\\'s discover feed', adminBase: '/api/v2/admin/discover-heroes', listKey: 'heroes', folder: 'discover_heroes' }} />;\n}\n", 'app/admin/content/muse-pool/page.tsx': "'use client';\nimport ContentPage from '../../ContentPage';\nexport default function MusePoolPage() {\n  return <ContentPage cfg={{ title: 'Muse Pool', sub: 'Pre-seeded into every new bride\\'s muse board on sign-up', adminBase: '/api/v2/admin/muse-pool', listKey: 'images', max: 20, folder: 'muse_pool' }} />;\n}\n", 'app/admin/content/surprise-me/page.tsx': "'use client';\nimport ContentPage from '../../ContentPage';\nexport default function SurpriseMePage() {\n  return <ContentPage cfg={{ title: 'Surprise Me', sub: 'Taste quiz image pool — up to 100 images', adminBase: '/api/v2/admin/surprise-pool', listKey: 'images', max: 100, folder: 'surprise_pool' }} />;\n}\n", 'app/admin/content/spotlight/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, Toast, UploadZone, ImageGrid, LoadingGrid, SectionDivider, BottomSheet, FieldInput, type ImageGridItem } from \'../../_components/AdminUI\';\nimport { spotlightApi, getVendors, type SpotlightItem, type AdminVendor } from \'../../../../lib/admin-api/index\';\nimport { adminUploadFile } from \'../../../../lib/admin-api/_base\';\n\nconst API_BASE  = process.env.NEXT_PUBLIC_API_BASE  || \'https://dream-os-production.up.railway.app\';\nconst ADMIN_PWD = process.env.NEXT_PUBLIC_ADMIN_PASSWORD || \'\';\n\nexport default function SpotlightPage() {\n  const [items, setItems]       = useState<SpotlightItem[]>([]);\n  const [vendors, setVendors]   = useState<AdminVendor[]>([]);\n  const [loading, setLoading]   = useState(true);\n  const [uploading, setUploading] = useState(false);\n  const [showAdd, setShowAdd]   = useState(false);\n  const [toast, setToast]       = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n\n  // Add form\n  const [caption, setCaption]     = useState(\'\');\n  const [weekLabel, setWeekLabel] = useState(\'\');\n  const [vendorId, setVendorId]   = useState(\'\');\n  const [pendingFile, setPendingFile] = useState<File | null>(null);\n  const [pendingUrl, setPendingUrl]   = useState(\'\');\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    Promise.all([spotlightApi.list(), getVendors()]).then(([s, v]) => {\n      setItems(s.spotlight);\n      setVendors(v.vendors);\n      setLoading(false);\n    }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const submit = async () => {\n    if (!pendingFile && !pendingUrl) return;\n    setUploading(true);\n    try {\n      let image_url = pendingUrl;\n      let cloudinary_public_id: string | undefined;\n      if (pendingFile) {\n        const r = await adminUploadFile(\'/api/v2/admin/spotlight/upload-url\', pendingFile);\n        image_url = r.image_url; cloudinary_public_id = r.cloudinary_public_id;\n      }\n      await fetch(`${API_BASE}/api/v2/admin/spotlight`, { method: \'POST\', headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD }, body: JSON.stringify({ image_url, cloudinary_public_id, vendor_id: vendorId || null, caption: caption || null, week_label: weekLabel || null }) });\n      showToast(\'Added to Spotlight.\');\n      setShowAdd(false); setCaption(\'\'); setWeekLabel(\'\'); setVendorId(\'\'); setPendingFile(null); setPendingUrl(\'\');\n      load();\n    } catch { showToast(\'Failed.\', true); }\n    finally { setUploading(false); }\n  };\n\n  const toggle = async (id: string, currentActive: boolean) => {\n    try {\n      await fetch(`${API_BASE}/api/v2/admin/spotlight/${id}`, { method: \'PATCH\', headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD }, body: JSON.stringify({ active: !currentActive }) });\n      setItems(prev => prev.map(i => i.id === id ? { ...i, active: !currentActive } : i));\n    } catch { showToast(\'Failed.\', true); }\n  };\n\n  const remove = async (id: string) => {\n    try {\n      await fetch(`${API_BASE}/api/v2/admin/spotlight/${id}`, { method: \'DELETE\', headers: { \'x-admin-password\': ADMIN_PWD } });\n      setItems(prev => prev.filter(i => i.id !== id));\n      showToast(\'Deleted.\');\n    } catch { showToast(\'Failed.\', true); }\n  };\n\n  const gridItems: ImageGridItem[] = items.map(i => ({\n    id: i.id, image_url: i.image_url, caption: i.caption, active: i.active,\n    extra: i.vendor_name ? <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.gold, padding: \'2px 0 6px\', letterSpacing: \'0.1em\' }}>{i.vendor_name} · {i.week_label || \'\'}</div> : undefined,\n  }));\n\n  return (\n    <div>\n      <PageHeader title="Spotlight" sub="Vendors of the week — shown in EXPLORE grid on discover landing" action={<GoldBtn label="Add" onClick={() => setShowAdd(true)} />} />\n\n      <SectionDivider label={`${items.length} spotlight card${items.length !== 1 ? \'s\' : \'\'}`} />\n      {loading ? <LoadingGrid /> : <ImageGrid items={gridItems} onToggle={toggle} onDelete={remove} />}\n\n      <BottomSheet visible={showAdd} onClose={() => setShowAdd(false)} title="Add to Spotlight">\n        <UploadZone\n          onFile={async (file) => { setPendingFile(file); setPendingUrl(\'\'); }}\n          onUrl={async (url) => { setPendingUrl(url); setPendingFile(null); }}\n          loading={false}\n        />\n        {(pendingFile || pendingUrl) && (\n          <div style={{ background: \'rgba(201,168,76,0.08)\', border: `0.5px solid ${T.borderStrong}`, borderRadius: 8, padding: \'10px 14px\', marginBottom: 16, fontFamily: T.ff.label, fontSize: 9, color: T.gold, letterSpacing: \'0.1em\' }}>\n            {pendingFile ? pendingFile.name : \'🔗 URL ready\'}\n          </div>\n        )}\n        <FieldInput label="Caption (optional)" value={caption} onChange={setCaption} placeholder="India\'s finest this week" />\n        <FieldInput label="Week label (optional)" value={weekLabel} onChange={setWeekLabel} placeholder="May 2026" />\n        <div style={{ marginBottom: 16 }}>\n          <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\' as const, marginBottom: 8 }}>Link to Vendor (optional)</div>\n          <select value={vendorId} onChange={e => setVendorId(e.target.value)} style={{ width: \'100%\', background: \'#141210\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'12px 14px\', fontFamily: T.ff.body, fontSize: 13, color: T.ink, outline: \'none\', minHeight: 44, appearance: \'none\' as const }}>\n            <option value="">No vendor link</option>\n            {vendors.map(v => <option key={v.id} value={v.id}>{v.name} — {v.category}</option>)}\n          </select>\n        </div>\n        <div style={{ paddingBottom: 12 }}>\n          <GoldBtn label={uploading ? \'Adding…\' : \'Add to Spotlight\'} onClick={submit} disabled={uploading || (!pendingFile && !pendingUrl)} />\n        </div>\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/approvals/photos/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, FieldSelect, BottomSheet, SectionDivider } from \'../../_components/AdminUI\';\nimport { getPhotoQueue, approvePhoto, rejectPhoto, type PhotoQueueItem } from \'../../../../lib/admin-api/index\';\n\nconst CATEGORIES = [\n  { value: \'\', label: \'All categories\' },\n  { value: \'photographer\', label: \'Photographer\' },\n  { value: \'videographer\', label: \'Videographer\' },\n  { value: \'mua\', label: \'MUA\' },\n  { value: \'decor\', label: \'Decor\' },\n  { value: \'venue\', label: \'Venue\' },\n  { value: \'caterer\', label: \'Caterer\' },\n];\nconst STATES = [\n  { value: \'pending\',  label: \'Pending\' },\n  { value: \'approved\', label: \'Approved\' },\n  { value: \'rejected\', label: \'Rejected\' },\n  { value: \'all\',      label: \'All\' },\n];\n\nexport default function PhotosPage() {\n  const [photos, setPhotos]   = useState<PhotoQueueItem[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [category, setCategory] = useState(\'\');\n  const [state, setState]     = useState(\'pending\');\n  const [selected, setSelected] = useState<PhotoQueueItem | null>(null);\n  const [rejectReason, setRejectReason] = useState(\'\');\n  const [toast, setToast]     = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getPhotoQueue({ state, ...(category ? { category } : {}) })\n      .then(d => { setPhotos(d.photos); setLoading(false); })\n      .catch(() => setLoading(false));\n  }, [state, category]);\n  useEffect(() => { load(); }, [load]);\n\n  const approve = async (id: string) => {\n    try { await approvePhoto(id); setPhotos(p => p.filter(x => x.id !== id)); showToast(\'Approved.\'); setSelected(null); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  const reject = async (id: string) => {\n    try { await rejectPhoto(id, rejectReason || undefined); setPhotos(p => p.filter(x => x.id !== id)); showToast(\'Rejected.\'); setSelected(null); setRejectReason(\'\'); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  return (\n    <div>\n      <PageHeader title="Photo Approvals" sub="Vendor portfolio photo queue" />\n\n      <div style={{ display: \'flex\', gap: 10, marginBottom: 20 }}>\n        <div style={{ flex: 1 }}>\n          <FieldSelect label="State" value={state} onChange={setState} options={STATES} />\n        </div>\n        <div style={{ flex: 1 }}>\n          <FieldSelect label="Category" value={category} onChange={setCategory} options={CATEGORIES} />\n        </div>\n      </div>\n\n      <SectionDivider label={`${photos.length} photo${photos.length !== 1 ? \'s\' : \'\'}`} />\n\n      {loading ? (\n        <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(2,1fr)\', gap: 12 }}>\n          {[1,2,3,4].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, aspectRatio: \'3/4\' }} />)}\n        </div>\n      ) : photos.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>Queue is clear</div>\n      ) : (\n        <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(2,1fr)\', gap: 12 }}>\n          {photos.map(p => (\n            <div key={p.id} onClick={() => setSelected(p)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, overflow: \'hidden\', cursor: \'pointer\' }}>\n              <div style={{ aspectRatio: \'3/4\', background: \'#1A1614\', overflow: \'hidden\' }}>\n                {/* eslint-disable-next-line @next/next/no-img-element */}\n                <img src={p.image_url} alt="" style={{ width: \'100%\', height: \'100%\', objectFit: \'cover\' }} loading="lazy" />\n              </div>\n              <div style={{ padding: \'10px 12px 12px\' }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 12, color: T.ink, marginBottom: 2, overflow: \'hidden\', textOverflow: \'ellipsis\', whiteSpace: \'nowrap\' }}>{p.vendor?.business_name || \'Unknown\'}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.soft, letterSpacing: \'0.1em\' }}>{p.vendor?.category}</div>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <BottomSheet visible={!!selected} onClose={() => { setSelected(null); setRejectReason(\'\'); }} title="Review Photo">\n        {selected && (\n          <div>\n            <div style={{ aspectRatio: \'4/3\', background: \'#1A1614\', borderRadius: 10, overflow: \'hidden\', marginBottom: 16 }}>\n              {/* eslint-disable-next-line @next/next/no-img-element */}\n              <img src={selected.image_url} alt="" style={{ width: \'100%\', height: \'100%\', objectFit: \'cover\' }} />\n            </div>\n            <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.ink, marginBottom: 4 }}>{selected.vendor?.business_name}</div>\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\', marginBottom: 20 }}>{selected.vendor?.category} · {selected.vendor?.routing_handle}</div>\n\n            <div style={{ marginBottom: 12 }}>\n              <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\' as const, marginBottom: 8 }}>Reject reason (optional)</div>\n              <input value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder="Not on-brand, low quality…" style={{ width: \'100%\', background: \'rgba(255,255,255,0.04)\', border: `0.5px solid ${T.border}`, borderRadius: 8, padding: \'12px 14px\', fontFamily: T.ff.body, fontSize: 13, color: T.ink, outline: \'none\', minHeight: 44 }} />\n            </div>\n\n            <div style={{ display: \'flex\', gap: 10, paddingBottom: 12 }}>\n              <GhostBtn label="Reject" onClick={() => reject(selected.id)} danger />\n              <GoldBtn label="Approve" onClick={() => approve(selected.id)} />\n            </div>\n          </div>\n        )}\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/approvals/discover/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, BottomSheet } from \'../../_components/AdminUI\';\nimport { getDiscoverQueue, grantDiscover, denyDiscover, revokeDiscover, type DiscoverRequest } from \'../../../../lib/admin-api/index\';\n\nconst STATE_COLORS: Record<string, string> = {\n  under_review: \'#C9A84C\', approved: \'#5CE0A0\', denied: \'#E05C5C\', revoked: \'#888\', not_requested: \'#444\',\n};\n\nexport default function DiscoverApprovalsPage() {\n  const [requests, setRequests] = useState<DiscoverRequest[]>([]);\n  const [loading, setLoading]   = useState(true);\n  const [selected, setSelected] = useState<DiscoverRequest | null>(null);\n  const [toast, setToast]       = useState(\'\');\n  const [toastErr, setToastErr] = useState(false);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getDiscoverQueue().then(d => { setRequests((d as any).requests || []); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const grant = async (id: string) => {\n    try { await grantDiscover(id); showToast(\'Approved for Discover.\'); load(); setSelected(null); }\n    catch { showToast(\'Failed.\', true); }\n  };\n  const deny = async (id: string) => {\n    try { await denyDiscover(id); showToast(\'Denied.\'); load(); setSelected(null); }\n    catch { showToast(\'Failed.\', true); }\n  };\n  const revoke = async (id: string) => {\n    try { await revokeDiscover(id); showToast(\'Revoked.\'); load(); setSelected(null); }\n    catch { showToast(\'Failed.\', true); }\n  };\n\n  const pending = requests.filter(r => r.discover_request_state === \'under_review\');\n  const rest    = requests.filter(r => r.discover_request_state !== \'under_review\');\n\n  return (\n    <div>\n      <PageHeader title="Discover Queue" sub={`${pending.length} pending review`} />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {[1,2,3].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 72 }} />)}\n        </div>\n      ) : requests.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>No requests</div>\n      ) : (\n        <>\n          {[...pending, ...rest].map(r => (\n            <div key={r.vendor_id} onClick={() => setSelected(r)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: 16, display: \'flex\', alignItems: \'center\', gap: 12, marginBottom: 8, cursor: \'pointer\', minHeight: 72 }}>\n              <div style={{ flex: 1 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.ink, marginBottom: 2 }}>{r.vendor_name}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, letterSpacing: \'0.1em\' }}>{r.vendor_category} · {r.vendor_city} · {r.portfolio_count} photos</div>\n              </div>\n              <span style={{ fontFamily: T.ff.label, fontSize: 7, letterSpacing: \'0.15em\', textTransform: \'uppercase\' as const, color: STATE_COLORS[r.discover_request_state] || T.soft, border: `0.5px solid ${STATE_COLORS[r.discover_request_state] || T.border}`, borderRadius: 20, padding: \'3px 10px\', flexShrink: 0 }}>\n                {r.discover_request_state.replace(\'_\', \' \')}\n              </span>\n            </div>\n          ))}\n        </>\n      )}\n\n      <BottomSheet visible={!!selected} onClose={() => setSelected(null)} title={selected?.vendor_name || \'\'}>\n        {selected && (\n          <div>\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, marginBottom: 20, letterSpacing: \'0.1em\' }}>{selected.vendor_category} · {selected.vendor_city} · {selected.portfolio_count} portfolio photos</div>\n            <div style={{ display: \'flex\', gap: 10, marginBottom: 12, flexWrap: \'wrap\' as const }}>\n              {selected.discover_request_state === \'under_review\' && (\n                <>\n                  <GoldBtn label="Approve" onClick={() => grant(selected.vendor_id)} />\n                  <GhostBtn label="Deny" onClick={() => deny(selected.vendor_id)} danger />\n                </>\n              )}\n              {selected.discover_request_state === \'approved\' && (\n                <GhostBtn label="Revoke Access" onClick={() => revoke(selected.vendor_id)} danger />\n              )}\n              {selected.discover_request_state === \'denied\' && (\n                <GoldBtn label="Approve Anyway" onClick={() => grant(selected.vendor_id)} />\n              )}\n            </div>\n          </div>\n        )}\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n', 'app/admin/conversations/vendors/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, Toast, BottomSheet } from \'../../_components/AdminUI\';\nimport { getVendorThreads, getMessages, type ConversationThread, type Message } from \'../../../../lib/admin-api/index\';\n\nfunction timeAgo(d: string) {\n  const diff = Date.now() - new Date(d).getTime();\n  const m = Math.floor(diff / 60000);\n  const h = Math.floor(diff / 3600000);\n  const dd = Math.floor(diff / 86400000);\n  if (m < 1) return \'just now\';\n  if (m < 60) return `${m}m ago`;\n  if (h < 24) return `${h}h ago`;\n  return `${dd}d ago`;\n}\n\nfunction MessageBubble({ msg }: { msg: Message }) {\n  const isAgent   = msg.sent_by === \'agent\';\n  const isVendor  = msg.sent_by === \'vendor\';\n  const isSystem  = msg.sent_by === \'system\';\n\n  if (isSystem) return (\n    <div style={{ textAlign: \'center\', padding: \'4px 0\' }}>\n      <span style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.1em\' }}>{msg.body}</span>\n    </div>\n  );\n\n  return (\n    <div style={{ display: \'flex\', justifyContent: isVendor ? \'flex-end\' : \'flex-start\', marginBottom: 8 }}>\n      <div style={{ maxWidth: \'80%\', background: isVendor ? T.gold : \'rgba(255,255,255,0.06)\', border: isVendor ? \'none\' : `0.5px solid ${T.border}`, borderRadius: isVendor ? \'16px 4px 16px 16px\' : \'4px 16px 16px 16px\', padding: \'10px 14px\' }}>\n        <div style={{ fontFamily: T.ff.body, fontSize: 13, fontWeight: 300, color: isVendor ? \'#0A0908\' : T.ink, lineHeight: 1.5, whiteSpace: \'pre-wrap\', wordBreak: \'break-word\' }}>{msg.body}</div>\n        <div style={{ fontFamily: T.ff.label, fontSize: 7, color: isVendor ? \'rgba(10,9,8,0.5)\' : T.muted, marginTop: 4, letterSpacing: \'0.1em\', textAlign: \'right\' as const }}>{msg.channel} · {timeAgo(msg.created_at)}</div>\n      </div>\n    </div>\n  );\n}\n\nexport default function VendorConversationsPage() {\n  const [threads, setThreads]   = useState<ConversationThread[]>([]);\n  const [loading, setLoading]   = useState(true);\n  const [selected, setSelected] = useState<ConversationThread | null>(null);\n  const [messages, setMessages] = useState<Message[]>([]);\n  const [loadingMsgs, setLoadingMsgs] = useState(false);\n  const [toast, setToast]       = useState(\'\');\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getVendorThreads().then(d => { setThreads(d.threads); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const openThread = async (thread: ConversationThread) => {\n    setSelected(thread); setMessages([]); setLoadingMsgs(true);\n    try { const d = await getMessages(thread.id); setMessages(d.messages); }\n    catch { setToast(\'Failed to load messages.\'); }\n    finally { setLoadingMsgs(false); }\n  };\n\n  return (\n    <div>\n      <PageHeader title="Vendor Chats" sub="WhatsApp + PWA conversations with the agent" />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {[1,2,3,4].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 68 }} />)}\n        </div>\n      ) : threads.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>No conversations yet</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 6 }}>\n          {threads.map(t => (\n            <div key={t.id} onClick={() => openThread(t)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: \'14px 16px\', display: \'flex\', alignItems: \'center\', gap: 12, cursor: \'pointer\', minHeight: 68 }}>\n              <div style={{ width: 36, height: 36, borderRadius: \'50%\', background: \'rgba(201,168,76,0.15)\', border: `0.5px solid ${T.borderStrong}`, display: \'flex\', alignItems: \'center\', justifyContent: \'center\', flexShrink: 0 }}>\n                <span style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 14, color: T.gold }}>{(t.vendor_name || \'V\')[0]}</span>\n              </div>\n              <div style={{ flex: 1, minWidth: 0 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.ink, marginBottom: 2, overflow: \'hidden\', textOverflow: \'ellipsis\', whiteSpace: \'nowrap\' }}>{t.vendor_name}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.soft, letterSpacing: \'0.1em\' }}>{t.vendor_category} · {t.vendor_tier}</div>\n              </div>\n              <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.08em\', flexShrink: 0 }}>{timeAgo(t.last_message_at)}</div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <BottomSheet visible={!!selected} onClose={() => setSelected(null)} title={selected?.vendor_name || \'Conversation\'}>\n        <div style={{ marginBottom: 20 }}>\n          {loadingMsgs ? (\n            <div style={{ textAlign: \'center\', padding: \'32px 0\', color: T.muted, fontFamily: T.ff.label, fontSize: 9, letterSpacing: \'0.15em\' }} className="shimmer">Loading messages…</div>\n          ) : (\n            <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 0, maxHeight: \'55vh\', overflowY: \'auto\', paddingBottom: 8 }}>\n              {messages.map(m => <MessageBubble key={m.id} msg={m} />)}\n            </div>\n          )}\n        </div>\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error />}\n    </div>\n  );\n}\n', 'app/admin/conversations/brides/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, Toast, BottomSheet } from \'../../_components/AdminUI\';\nimport { getBrideThreads, getMessages, type ConversationThread, type Message } from \'../../../../lib/admin-api/index\';\n\nfunction timeAgo(d: string) {\n  const diff = Date.now() - new Date(d).getTime();\n  const m = Math.floor(diff / 60000); const h = Math.floor(diff / 3600000); const dd = Math.floor(diff / 86400000);\n  if (m < 1) return \'just now\'; if (m < 60) return `${m}m ago`; if (h < 24) return `${h}h ago`; return `${dd}d ago`;\n}\n\nfunction MessageBubble({ msg }: { msg: Message }) {\n  const isBride = msg.sent_by === \'couple\' || msg.direction === \'inbound\';\n  if (msg.sent_by === \'system\') return (\n    <div style={{ textAlign: \'center\', padding: \'4px 0\' }}>\n      <span style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.1em\' }}>{msg.body}</span>\n    </div>\n  );\n  return (\n    <div style={{ display: \'flex\', justifyContent: isBride ? \'flex-end\' : \'flex-start\', marginBottom: 8 }}>\n      <div style={{ maxWidth: \'80%\', background: isBride ? \'rgba(245,240,232,0.12)\' : \'rgba(201,168,76,0.08)\', border: `0.5px solid ${isBride ? \'rgba(245,240,232,0.15)\' : T.borderStrong}`, borderRadius: isBride ? \'16px 4px 16px 16px\' : \'4px 16px 16px 16px\', padding: \'10px 14px\' }}>\n        <div style={{ fontFamily: T.ff.body, fontSize: 13, fontWeight: 300, color: T.ink, lineHeight: 1.5, whiteSpace: \'pre-wrap\', wordBreak: \'break-word\' }}>{msg.body}</div>\n        <div style={{ fontFamily: T.ff.label, fontSize: 7, color: T.muted, marginTop: 4, letterSpacing: \'0.1em\', textAlign: \'right\' as const }}>{msg.channel} · {timeAgo(msg.created_at)}</div>\n      </div>\n    </div>\n  );\n}\n\nexport default function BrideConversationsPage() {\n  const [threads, setThreads]   = useState<ConversationThread[]>([]);\n  const [loading, setLoading]   = useState(true);\n  const [selected, setSelected] = useState<ConversationThread | null>(null);\n  const [messages, setMessages] = useState<Message[]>([]);\n  const [loadingMsgs, setLoadingMsgs] = useState(false);\n  const [toast, setToast]       = useState(\'\');\n\n  const load = useCallback(() => {\n    setLoading(true);\n    getBrideThreads().then(d => { setThreads(d.threads); setLoading(false); }).catch(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const openThread = async (thread: ConversationThread) => {\n    setSelected(thread); setMessages([]); setLoadingMsgs(true);\n    try { const d = await getMessages(thread.id); setMessages(d.messages); }\n    catch { setToast(\'Failed to load messages.\'); }\n    finally { setLoadingMsgs(false); }\n  };\n\n  return (\n    <div>\n      <PageHeader title="Bride Chats" sub="Bride conversations with DreamAi" />\n\n      {loading ? (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 8 }}>\n          {[1,2,3,4].map(i => <div key={i} className="shimmer" style={{ background: T.card, borderRadius: 12, height: 68 }} />)}\n        </div>\n      ) : threads.length === 0 ? (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\', color: T.muted, fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 18 }}>No conversations yet</div>\n      ) : (\n        <div style={{ display: \'flex\', flexDirection: \'column\' as const, gap: 6 }}>\n          {threads.map(t => (\n            <div key={t.id} onClick={() => openThread(t)} style={{ background: T.card, border: `0.5px solid ${T.border}`, borderRadius: 12, padding: \'14px 16px\', display: \'flex\', alignItems: \'center\', gap: 12, cursor: \'pointer\', minHeight: 68 }}>\n              <div style={{ width: 36, height: 36, borderRadius: \'50%\', background: \'rgba(245,240,232,0.06)\', border: `0.5px solid ${T.border}`, display: \'flex\', alignItems: \'center\', justifyContent: \'center\', flexShrink: 0 }}>\n                <span style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 14, color: T.ink }}>{(t.bride_name || \'B\')[0]}</span>\n              </div>\n              <div style={{ flex: 1, minWidth: 0 }}>\n                <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.ink, marginBottom: 2, overflow: \'hidden\', textOverflow: \'ellipsis\', whiteSpace: \'nowrap\' }}>{t.bride_name}</div>\n                <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.soft, letterSpacing: \'0.1em\' }}>{t.wedding_city || \'City TBD\'}{t.wedding_date ? ` · ${new Date(t.wedding_date).toLocaleDateString(\'en-IN\', { month: \'short\', year: \'numeric\' })}` : \'\'}</div>\n              </div>\n              <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, flexShrink: 0 }}>{timeAgo(t.last_message_at)}</div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <BottomSheet visible={!!selected} onClose={() => setSelected(null)} title={selected?.bride_name || \'Conversation\'}>\n        <div style={{ marginBottom: 20 }}>\n          {loadingMsgs ? (\n            <div style={{ textAlign: \'center\', padding: \'32px 0\' }} className="shimmer">\n              <span style={{ fontFamily: T.ff.label, fontSize: 9, color: T.muted, letterSpacing: \'0.15em\' }}>Loading…</span>\n            </div>\n          ) : (\n            <div style={{ display: \'flex\', flexDirection: \'column\' as const, maxHeight: \'55vh\', overflowY: \'auto\', paddingBottom: 8 }}>\n              {messages.map(m => <MessageBubble key={m.id} msg={m} />)}\n            </div>\n          )}\n        </div>\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error />}\n    </div>\n  );\n}\n', 'app/admin/vendors/portfolio/page.tsx': '\'use client\';\nimport { useEffect, useState, useCallback } from \'react\';\nimport { PageHeader, T, GoldBtn, GhostBtn, Toast, UploadZone, ImageGrid, LoadingGrid, SectionDivider, BottomSheet, FieldInput, type ImageGridItem } from \'../../_components/AdminUI\';\nimport { getVendors, type AdminVendor } from \'../../../../lib/admin-api/index\';\nimport { adminUploadFile } from \'../../../../lib/admin-api/_base\';\n\nconst API_BASE  = process.env.NEXT_PUBLIC_API_BASE  || \'https://dream-os-production.up.railway.app\';\nconst ADMIN_PWD = process.env.NEXT_PUBLIC_ADMIN_PASSWORD || \'\';\n\ntype PortfolioPhoto = {\n  id: string; image_url: string; caption: string | null;\n  aesthetic_tags: string[]; is_hero: boolean; in_carousel: boolean;\n  approval_state: string; created_at: string;\n};\n\nexport default function VendorPortfolioPage() {\n  const [vendors, setVendors]       = useState<AdminVendor[]>([]);\n  const [vendorId, setVendorId]     = useState(\'\');\n  const [photos, setPhotos]         = useState<PortfolioPhoto[]>([]);\n  const [loading, setLoading]       = useState(false);\n  const [uploading, setUploading]   = useState(false);\n  const [toast, setToast]           = useState(\'\');\n  const [toastErr, setToastErr]     = useState(false);\n  const [caption, setCaption]       = useState(\'\');\n  const [showCaption, setShowCaption] = useState(false);\n  const [pendingUpload, setPendingUpload] = useState<{ type: \'file\'; file: File } | { type: \'url\'; url: string } | null>(null);\n\n  const showToast = (msg: string, err = false) => { setToast(msg); setToastErr(err); };\n\n  // Load vendor list once\n  useEffect(() => {\n    getVendors().then(d => setVendors(d.vendors)).catch(() => {});\n  }, []);\n\n  const selectedVendor = vendors.find(v => v.id === vendorId);\n\n  const loadPhotos = useCallback(async (vid: string) => {\n    if (!vid) return;\n    setLoading(true);\n    try {\n      const res = await fetch(`${API_BASE}/api/v2/admin/vendors/${vid}/portfolio`, {\n        headers: { \'x-admin-password\': ADMIN_PWD },\n      });\n      const d = await res.json();\n      setPhotos(d.photos || []);\n    } catch { showToast(\'Failed to load photos.\', true); }\n    finally { setLoading(false); }\n  }, []);\n\n  const handleVendorChange = (vid: string) => {\n    setVendorId(vid);\n    setPhotos([]);\n    if (vid) loadPhotos(vid);\n  };\n\n  // When user picks a file or URL — show caption sheet before uploading\n  const handleFile = async (file: File) => {\n    setPendingUpload({ type: \'file\', file });\n    setCaption(\'\');\n    setShowCaption(true);\n  };\n\n  const handleUrl = async (url: string) => {\n    setPendingUpload({ type: \'url\', url });\n    setCaption(\'\');\n    setShowCaption(true);\n  };\n\n  const submitUpload = async () => {\n    if (!pendingUpload || !vendorId) return;\n    setUploading(true);\n    setShowCaption(false);\n    try {\n      let image_url = \'\';\n      if (pendingUpload.type === \'file\') {\n        const r = await adminUploadFile(`/api/v2/admin/vendors/${vendorId}/portfolio/upload-url`, pendingUpload.file);\n        image_url = r.image_url;\n      } else {\n        image_url = pendingUpload.url;\n      }\n      await fetch(`${API_BASE}/api/v2/admin/vendors/${vendorId}/portfolio`, {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD },\n        body: JSON.stringify({ image_url, caption: caption.trim() || null }),\n      });\n      showToast(\'Photo added.\');\n      setPendingUpload(null);\n      setCaption(\'\');\n      loadPhotos(vendorId);\n    } catch { showToast(\'Upload failed.\', true); }\n    finally { setUploading(false); }\n  };\n\n  const deletePhoto = async (id: string) => {\n    try {\n      await fetch(`${API_BASE}/api/v2/admin/vendors/${vendorId}/portfolio/${id}`, {\n        method: \'DELETE\', headers: { \'x-admin-password\': ADMIN_PWD },\n      });\n      setPhotos(prev => prev.filter(p => p.id !== id));\n      showToast(\'Deleted.\');\n    } catch { showToast(\'Failed to delete.\', true); }\n  };\n\n  // Toggle is_hero\n  const toggleHero = async (id: string, currentHero: boolean) => {\n    try {\n      await fetch(`${API_BASE}/api/v2/admin/vendors/${vendorId}/portfolio/${id}`, {\n        method: \'PATCH\',\n        headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD },\n        body: JSON.stringify({ is_hero: !currentHero }),\n      });\n      setPhotos(prev => prev.map(p => ({ ...p, is_hero: p.id === id ? !currentHero : (currentHero ? false : p.is_hero) })));\n      showToast(!currentHero ? \'Set as hero.\' : \'Hero removed.\');\n    } catch { showToast(\'Failed.\', true); }\n  };\n\n  // Map to ImageGrid format — active = in_carousel, extra shows hero badge + tags\n  const gridItems: ImageGridItem[] = photos.map(p => ({\n    id: p.id,\n    image_url: p.image_url,\n    caption: p.caption,\n    active: p.in_carousel,\n    extra: (\n      <div style={{ display: \'flex\', gap: 6, flexWrap: \'wrap\' as const, padding: \'4px 0 8px\' }}>\n        {p.is_hero && (\n          <span style={{ fontFamily: T.ff.label, fontSize: 7, color: T.gold, border: `0.5px solid ${T.borderStrong}`, borderRadius: 20, padding: \'2px 8px\', letterSpacing: \'0.1em\' }}>HERO</span>\n        )}\n        {(p.aesthetic_tags || []).slice(0, 2).map((tag: string) => (\n          <span key={tag} style={{ fontFamily: T.ff.label, fontSize: 7, color: T.muted, border: `0.5px solid ${T.border}`, borderRadius: 20, padding: \'2px 8px\' }}>{tag}</span>\n        ))}\n      </div>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title="Vendor Portfolio" sub="Upload photos on behalf of any vendor — auto-approved, feeds the discover grid" />\n\n      {/* Vendor picker */}\n      <div style={{ marginBottom: 24 }}>\n        <div style={{ fontFamily: T.ff.label, fontWeight: 200, fontSize: 8, color: T.soft, letterSpacing: \'0.22em\', textTransform: \'uppercase\' as const, marginBottom: 8 }}>Select Vendor</div>\n        <select\n          value={vendorId}\n          onChange={e => handleVendorChange(e.target.value)}\n          style={{ width: \'100%\', background: \'#141210\', border: `0.5px solid ${vendorId ? T.gold : T.border}`, borderRadius: 10, padding: \'14px 16px\', fontFamily: T.ff.body, fontSize: 14, color: vendorId ? T.ink : T.soft, outline: \'none\', minHeight: 52, appearance: \'none\' as const }}\n        >\n          <option value="">— Choose a vendor —</option>\n          {vendors.map(v => (\n            <option key={v.id} value={v.id}>{v.name} {v.category ? `· ${v.category}` : \'\'} {v.city ? `· ${v.city}` : \'\'}</option>\n          ))}\n        </select>\n      </div>\n\n      {/* Selected vendor pill */}\n      {selectedVendor && (\n        <div style={{ display: \'flex\', alignItems: \'center\', gap: 12, background: \'rgba(201,168,76,0.06)\', border: `0.5px solid ${T.borderStrong}`, borderRadius: 12, padding: \'12px 16px\', marginBottom: 24 }}>\n          <div style={{ width: 32, height: 32, borderRadius: \'50%\', background: \'rgba(201,168,76,0.15)\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', flexShrink: 0 }}>\n            <span style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 14, color: T.gold }}>{selectedVendor.name[0]}</span>\n          </div>\n          <div>\n            <div style={{ fontFamily: T.ff.body, fontSize: 14, color: T.ink }}>{selectedVendor.name}</div>\n            <div style={{ fontFamily: T.ff.label, fontSize: 8, color: T.soft, letterSpacing: \'0.1em\' }}>{selectedVendor.category || \'—\'} · {selectedVendor.city || \'—\'} · {selectedVendor.tier}</div>\n          </div>\n          <div style={{ marginLeft: \'auto\', fontFamily: T.ff.label, fontSize: 8, color: T.soft }}>\n            {photos.length} photo{photos.length !== 1 ? \'s\' : \'\'}\n          </div>\n        </div>\n      )}\n\n      {vendorId && (\n        <>\n          <UploadZone onFile={handleFile} onUrl={handleUrl} loading={uploading} />\n          <SectionDivider label={`${photos.length} photo${photos.length !== 1 ? \'s\' : \'\'} in portfolio`} />\n          {loading ? <LoadingGrid /> : (\n            <>\n              {photos.length > 0 && (\n                <p style={{ fontFamily: T.ff.label, fontSize: 8, color: T.muted, letterSpacing: \'0.12em\', marginBottom: 16 }}>\n                  Tap Activate/Deactivate to toggle carousel. All photos are auto-approved.\n                </p>\n              )}\n              <ImageGrid\n                items={gridItems}\n                onToggle={async (id, active) => {\n                  try {\n                    await fetch(`${API_BASE}/api/v2/admin/vendors/${vendorId}/portfolio/${id}`, {\n                      method: \'PATCH\',\n                      headers: { \'Content-Type\': \'application/json\', \'x-admin-password\': ADMIN_PWD },\n                      body: JSON.stringify({ in_carousel: !active }),\n                    });\n                    setPhotos(prev => prev.map(p => p.id === id ? { ...p, in_carousel: !active } : p));\n                  } catch { showToast(\'Failed.\', true); }\n                }}\n                onDelete={deletePhoto}\n              />\n            </>\n          )}\n        </>\n      )}\n\n      {!vendorId && (\n        <div style={{ textAlign: \'center\', padding: \'48px 0\' }}>\n          <div style={{ fontFamily: T.ff.display, fontStyle: \'italic\', fontSize: 22, color: T.muted, marginBottom: 8 }}>Select a vendor above</div>\n          <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.muted, letterSpacing: \'0.18em\' }}>to upload or manage their portfolio</div>\n        </div>\n      )}\n\n      {/* Caption sheet — shown before upload */}\n      <BottomSheet visible={showCaption} onClose={() => { setShowCaption(false); setPendingUpload(null); }} title="Add Caption">\n        <div style={{ marginBottom: 8 }}>\n          {pendingUpload?.type === \'file\' && (\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.soft, marginBottom: 16 }}>📎 {(pendingUpload as any).file.name}</div>\n          )}\n          {pendingUpload?.type === \'url\' && (\n            <div style={{ fontFamily: T.ff.label, fontSize: 9, color: T.gold, marginBottom: 16, wordBreak: \'break-all\' }}>🔗 URL ready</div>\n          )}\n          <FieldInput label="Caption (optional)" value={caption} onChange={setCaption} placeholder="Bridal lehenga shoot, Delhi 2025…" />\n          <div style={{ paddingBottom: 12 }}>\n            <GoldBtn label={uploading ? \'Uploading…\' : \'Upload Photo\'} onClick={submitUpload} disabled={uploading} />\n          </div>\n        </div>\n      </BottomSheet>\n\n      {toast && <Toast msg={toast} onDone={() => setToast(\'\')} error={toastErr} />}\n    </div>\n  );\n}\n'}
